(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["bg"] = {"ui":{"skip":"Към съдържанието","back":"← Обратно към AI-gile","lang.button":"Език: {name}","lang.dialog":"Избери език","lang.search":"Търси език","lang.none":"Няма съвпадащ език","lang.notYet":"{name} още не е преведен","theme.aria":"Смяна на темата: светла, тъмна или черна","theme.toLight":"Към светла тема","theme.toDark":"Към тъмна тема","theme.toBlack":"Към черна тема (истинско черно, щадящо OLED екраните)","words.underline":"Подчертай тези думи на страницата","words.underlineHelp":"Посочи или докосни дума с точки отдолу, за да видиш какво означава.","words.col.todo":"Избрани за момента карти: екипът започва с тях след това.","words.col.doing":"Един AI работи по тази карта в момента.","words.col.review":"Един AI е свършил работата; друг я проверява, преди да стигне до теб.","words.col.verify":"Чака теб: пробвай го и кажи дали работи.","words.col.team":"Твоите бележки или отговори, които чакат екипът да ги поеме.","words.col.done":"Завършено и прието.","index.title":"AI-gile: твоят AI екип за разработка, на една дъска","index.description":"AI-gile е канбан дъска за екипи, които кодират с изкуствен интелект. Те работят, докато спиш; ти получаваш една кратка купчинка неща за решаване, тестване и приемане.","hero.logoAlt":"Икона на дъската на AI-gile","hero.h1.html":"Твоят AI екип за разработка, на една&nbsp;дъска.","hero.alpha":"🐣 Затворена пре-алфа","hero.alphaTitle":"Рано и недовършено: благодаря, че го пробваш!","hero.lede":"Те строят, докато спиш. Събуждаш се с една кратка купчинка: няколко въпроса, няколко неща за тестване, един-два лилави диаманта. Кликваш, приемаш и се връщаш към кафето си.","dl.windows":"Приложение за Windows","dl.browser":"Пусни го в браузъра","dl.messenger":"📱 Messenger за телефона ти","dl.soon":"Скоро","dl.notify":"🔔 Кажи ми, когато отвори","dl.notifySmall":"Алфа или бета","hero.secondary":"Аджайл, но екипът никога не се нуждае от кафе за стендъп. (Правят стендъпи така или иначе.)","pitch.h2":"AI-gile с колкото думи искаш","pitch.lede":"Избери дължина, от една дума до 144. Всяка дължина е отделно описание, написано за този размер. Плъзни плъзгача или използвай стрелките.","pitch.rangeLabel":"Дължина в думи","pitch.dice":"🎲 друга версия","pitch.words.one":"{n} дума","pitch.words.other":"{n} думи","pitch.letters.one":"{n} буква","pitch.letters.other":"{n} букви","pitch.chars.one":"{n} знак","pitch.chars.other":"{n} знака","count.line.html.one":"{n} карта на дъската в момента","count.line.html.other":"{n} карти на дъската в момента","people.humans.html.one":"👥 {n} човек","people.humans.html.other":"👥 {n} души","people.agents.html.one":"🤖 {n} агент","people.agents.html.other":"🤖 {n} агента","people.working.html.one":"⚡ {n} работи в момента","people.working.html.other":"⚡ {n} работят в момента","pre.title":"AI-gile: тук се строи нещо","pre.description":"Тук се строи нещо. Дъска, на която AI екипи създават каквото поискаш и те учат по пътя. Засега затворена пре-алфа с приятели.","pre.h1":"Тук се строи нещо. 🤫","pre.line":"Дъска, на която AI екипи създават каквото поискаш и те учат по пътя. Засега затворена пре-алфа с приятели.","pre.btn":"🔔 Кажи ми, когато отвори","pre.peek":"Зад стъклото: истинската дъска, на живо. Всяка карта е цветна лента.","pre.peekFake":"Зад стъклото: така изглежда дъска в работа.","pre.night":"🌙 Нощният пазач поема щафетата · 😴 човекът почива","features.aria":"Какво прави","f.pile.h":"Една купчинка за теб","f.pile.html":"<b>За теб</b> събира всичко, което чака теб, във всички проекти: въпроси, неща за тестване, задачи, които може да свърши само човек. Опашката ти казва кое е следващо и колко ще отнеме.","f.sleep.h":"Екипи, които работят, докато спиш","f.sleep.p":"Всеки проект има лидер и екип от AI агенти. Коментирай карта и екипът се събужда, върши работата и ти я връща със стъпки, които един уморен човек може да следва.","f.tester.h":"Първо проверява AI тестер","f.tester.p":"Преди нещо да стигне до теб, тестер следва стъпките в копие на приложението и показва какво е видял, със снимка на екрана. Прегледай миналите и приеми с един клик.","f.proof.h":"Доказателства, не обещания","f.proof.p":"Всяко предаване показва какво се е променило: файловете, разликата, снимките на екрана. Не е нужно да отваряш всяко приложение, за да видиш дали е готово.","f.chat.h":"Чати с лидерите си","f.chat.p":"Странична лента като в Discord: една икона за проект, лилави диаманти за онова, което чака теб. Пиши на лидер идея; той я превръща в карти и план, с бутон ✅ Давай.","f.tidy.h":"Подрежда се сам","f.tidy.p":"Сродните карти се сливат в една, объркани заглавия се оправят, а проверка на токените държи кода компактен. По-малко неща за превключване, по-малко за мислене.","f.private.h":"Твое, на твоя компютър","f.private.li1":"Дъската работи на твоята собствена машина и отговаря само на теб.","f.private.li2":"Личните съобщения между хората са шифровани от край до край.","f.private.li3":"Без акаунти, без тракери, без бисквитки.","f.lang.h":"На твоя език","f.lang.p":"Над 120 езика, от нидерландски, уелски и японски до пиратски, Йода и клингонски, с бързо превключване обратно към английски за професионалния жаргон.","f.service.h":"От идея до истинска услуга","f.service.p":"Създал си с AI нещо, което хората вече ползват? Отбележи го като услуга и дъската ще ти помогне да го поддържаш добре: проверки на работоспособността, публична страница за състоянието, инциденти с анализ, промени, които искат Go, резервни копия, проверявани всеки ден. Помощта те учи на всяка стъпка по пътя.","msgr.h2":"AI-gile Messenger: екипът ти в джоба","msgr.p1":"Говори с AI екипа си, без да отваряш таблото. Пиши си с лидерите на проектите и с приятелите си, виж стъпките за тест на карта и им отговори, всичко от телефона.","msgr.p2":"За да го свържеш, сканирай QR код от таблото си. За първи път? Приятелски демо чат ще те разведе.","msgr.when":"Първо за Android, после уеб версия за телефони и iPhone.","msgr.who":"Лидерът на проекта ти","msgr.b1":"Поправката на тъмния режим е готова. Искаш ли стъпките за тест?","msgr.b2":"Да, моля!","msgr.b3":"1. Отвори Настройки. 2. Избери Тъмна. Изглежда ли наред?","tl.aria":"Времева линия от първия разговор до пътната карта","tl.h2":"От първия чат до следващото","tl.lede":"Истински дати и часове, в твоята часова зона. След днес това е планът, без обещани дати.","tl.today":"Днес","tl.planned":"планирано","tl.doing":"в процес","tl.cards.one":"{n} карта","tl.cards.other":"{n} карти","join.h2":"Включи се","join.lede":"AI-gile се прави от един брадат чудак с AuDHD и няколко битки с психичното здраве, и от много търпеливи агенти. Засега е частен, в затворена алфа с приятели. Искаш ли да го пробваш, когато се отвори?","join.btn":"Заяви интерес","join.small":"Ще ти пишем по имейл, нищо друго","footer.tag":"AI-gile. Без тракери, без бисквитки, без кафе за стендъп.","footer.licence":"Бизнес лиценз","footer.status":"Статус","footer.privacy":"Какво пазим","footer.thanks":"Разговорите благодарение на ChilledChat","form.sending":"Изпраща се…","form.failed":"Не се получи: опитай пак по-късно.","form.offline":"Не успяхме да стигнем до AI-gile: опитай пак по-късно.","form.keep":"Използваме това само за да ти отговорим, после го изтриваме. Без тракери, без бисквитки.","form.keepLink":"Какво пазим","interest.title":"AI-gile: кажи ми, когато алфата се отвори","interest.description":"Остави имейла си, за да научиш кога се отваря затворената алфа или бета на AI-gile.","interest.h1":"🔔 Кажи ми, когато отвори","interest.lede":"AI-gile е в затворена пре-алфа. Остави имейла си и ще ти пишем веднъж, когато има място за теб.","interest.email":"Твоят имейл","interest.which":"Кой тест?","interest.alpha":"Затворена алфа: рано, грубо, много промени","interest.beta":"Бета: по-стабилна, по-късно","interest.both":"Която и да е, която дойде първа","interest.submit":"Запиши ме в списъка","interest.thanks":"Благодаря! В списъка си.","licence.title":"AI-gile: бизнес лиценз","licence.description":"Използваш ли AI-gile в бизнеса си? Кандидатствай за безплатен бизнес лиценз.","licence.h1":"📜 Бизнес лиценз","licence.lede":"Използваш ли AI-gile на работа? Кажи ни кой си и с какво се занимаваш. Ако върши някаква полза, лицензът е безплатен.","licence.company":"Компания","licence.website":"Уебсайт","licence.what":"С какво се занимаваш","licence.how":"Как помага на света","licence.email":"Имейл","licence.submit":"Кандидатствай","licence.thanks":"Благодаря! Ще ти отговорим по имейл.","status.title":"Статус на AI-gile","status.h1":"Статус на AI-gile","status.quiet":"Всичко е тихо","status.intro":"Работи ли AI-gile в момента? Тази страница проверява сайта, споделянето на дъски, разговорите и изтеглянето на всеки 5 минути.","status.up":"Работи (отговори за {ms} ms)","status.slow":"Не отговори на последната проверка, опитваме пак","status.down":"Не работи: не отговори на последните две проверки","status.svc.web":"Уебсайт","status.svc.web.offers":"Този сайт: какво е AI-gile и формата за интерес","status.svc.boards":"Споделяне на дъски","status.svc.boards.offers":"Публични дъски, съобщения между приятели и покани","status.svc.calls":"Разговори","status.svc.calls.offers":"Глас, видео и споделяне на екрана в AI-gile","status.svc.download":"Изтегляне","status.svc.download.offers":"Инсталаторът за Windows и линковете за покани","status.checking":"Проверява се…","status.offline":"В момента не може да се стигне до услугата за статус (опитва се пак)","status.updated":"обновено {ago}","status.justNow":"току-що","status.min":"преди {n} мин","status.hours":"преди {n} ч","status.days":"преди {n} д","privacy.title":"AI-gile: какво пазим","privacy.h1":"Какво пазим","privacy.lede":"Накратко: само това, което ни пращаш, и не за дълго.","privacy.only":"Само това, което ни пращаш: каквото напишеш във формата, например имейла си. Нищо друго за теб.","privacy.sealed":"Запечатва се, така че сървърът ни да не може да го прочете: в браузъра ти, преди да тръгне (при по-стар браузър – в момента, в който пристигне). Само нашата собствена дъска може да го отвори.","privacy.server":"Изтрива се от сървъра веднага щом стигне до дъската ни. Всичко, което още е там след 30 дни, се изтрива така или иначе.","privacy.board":"Пазим го на дъската си само докато ти отговорим, после го изтриваме и оттам.","privacy.none":"Без тракери, без бисквитки, без анализи.","privacy.local":"Езикът ти и изборът на светла или тъмна тема остават в собствения ти браузър. Никога не ни се изпращат.","privacy.ask":"Искаш да изчезне по-рано? Отговори на имейла ни и ни кажи.","live.h2":"Гледайте как се изгражда, на живо","live.caption":"Всяка карта е скрита: виждате формата на работата, не думите.","live.watching.one":"на живо: {n} гледа","live.watching.other":"на живо: {n} гледат","live.last.now":"Последната карта е преместена току-що","live.last.min.one":"Последната карта е преместена преди {n} мин","live.last.min.other":"Последната карта е преместена преди {n} мин","live.last.hour.one":"Последната карта е преместена преди {n} час","live.last.hour.other":"Последната карта е преместена преди {n} часа","live.last.day.one":"Последната карта е преместена преди {n} ден","live.last.day.other":"Последната карта е преместена преди {n} дни","live.offline":"Таблото на живо си почива за малко. Заповядайте пак скоро.","live.cols":"Backlog|За изпълнение|В процес|Екипът проверява|Чака твоя тест|За екипа|Готово","footer.models":"AI-gile пуска AI модели за теб. Какво казват и правят е тяхна работа, така че проверявай, преди да им се довериш.","privacy.ai.h":"AI частта","privacy.ai.models":"AI-gile е таблото. Работата се върши от AI модели на други компании, като Claude, Codex и Gemini, с твоите собствени профили.","privacy.ai.check":"Каквото пишат и правят идва от тях и може да е грешно. Провери го, преди да разчиташ на него или да го пуснеш.","privacy.ai.files":"Те променят файлове и изпълняват команди в папките, които свържеш. Пази резервно копие.","privacy.ai.send":"Каквото дадеш на модел, отива при компанията, която го управлява, по нейните условия. Важат условията и цените на всеки от тях.","privacy.ai.asis":"AI-gile е ранна тестова версия, предоставена такава, каквато е."},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Канбан.","Роботи.","Делегирано."]},{"n":2,"texts":["Роботи, канбан.","Агенти, подредени.","Идеи, построени."]},{"n":3,"texts":["Канбан за роботи.","Идеите стават функции.","Безплатен канбан за агенти."]},{"n":5,"texts":["Канбан дъска, водена от агенти.","Ти пишеш карти. Агентите строят.","Безплатно, локално, тествано, малко смахнато."]},{"n":8,"texts":["Безплатна канбан дъска, където работят AI агенти.","Напиши идея. Агентите я строят. Ти я приемаш.","Аджайл за един човек и много търпеливи роботи."]},{"n":13,"texts":["Канбан дъска на твоя компютър, където AI агентите поемат картите и ги изпълняват.","Напиши идея. Екип от агенти я строи. Тестер я проверява накрая.","Безплатно, без акаунти, без тракери: дъска, няколко робота и ти, който решаваш."]},{"n":21,"texts":["AI-gile е канбан дъска за работа с AI агенти за кодиране. Те поемат картите, а ти ги тестваш и приемаш.","Всеки проект получава лидер и екип от AI агенти. Коментирай всяка карта и екипът се залавя за работа.","Безплатна лична дъска със задачи, която работи на твоя компютър. Работниците са роботи. Този, който казва да, си ти."]},{"n":34,"texts":["Слагаш идеи на дъска. Екип от AI агенти ги превръща в работещи функции, тества ги и ти ги връща със стъпки за изпробване. Нищо не се брои за готово, докато ти не кажеш.","AI-gile е домашно направена канбан дъска, която Рич построи с голяма помощ от агентите, които сега управлява. Безплатна е, работи на твоя компютър и се споделя с приятели, не се продава.","Представи си обикновена канбан дъска с колони от Backlog до Готово, само че картите се поемат от AI агенти. Те докладват напредъка, питат, когато заседнат, и винаги чакат твоето одобрение."]},{"n":55,"texts":["AI-gile е канбан дъска, на която екипът е съставен от AI агенти. Всеки проект има лидер, който планира работата, и помощници, които я строят. Когато една функция е готова, AI тестер я изпробва и прави снимка на екрана, след което тя пристига в твоята купчинка. Приеми я или коментирай и те я правят наново.","Започна като начин един човек да следи много сесии за кодиране с AI едновременно и порасна до истинска дъска. Работи на твоята машина, не иска акаунт и няма тракери. Безплатна е за приятели и за всеки любопитен. Също така е недовършена, така че очаквай някоя и друга грапавина и от време на време изненада.","Ето честната версия. Все още трябва ти да измисляш идеите и ти да проверяваш резултатите. AI-gile върши всичко помежду им: подрежда картите, буди правилния агент, когато коментираш, показва точно какво се е променило и държи всичко в една кратка купчинка за теб, без излишен шум."]},{"n":89,"texts":["AI-gile е безплатна канбан дъска, която пускаш на собствения си компютър. Вместо хора всеки проект има екип от AI агенти: лидер, който превръща идеите ти в карти и план, и помощници, които поемат картите по приоритет. Когато нещо е построено, AI тестер следва стъпките за тестване и ти показва какво е видял. После то чака в една купчинка, наречена За теб. Приемаш го или коментираш и екипът опитва отново. Нищо никога не стига до Готово без теб.","Има и функции, които може да не очакваш. Нощна стража държи колоната За правене пълна, докато спиш, като избира карти, които не искат отговор от теб. Брояч на токени показва колко са използвали агентите днес и тази седмица, а Режим без токени им казва да спрат да харчат. Можеш да пишеш на приятели, а личните съобщения са шифровани от край до край. Дъската говори около 120 езика, включително нидерландски, фламандски, пиратски и клингонски. Нищо от това не струва и стотинка и никой не се опитва да ти го продава.","AI-gile е малък личен проект, не компания. Рич искаше да се грижи за няколко проекта с AI кодиране, без да отваря всяко приложение, за да ги проверява, затова двамата с агентите построиха дъска за това, а после я използваха, за да построят останалата част от себе си. В затворена пре-алфа е, което значи, че работи, повечето време, за шепа приятели. Няма страница с цени, няма бюлетин и няма план за растеж. Ако ти звучи полезно, можеш да поискаш да го пробваш, когато се отвори малко повече."]},{"n":144,"texts":["AI-gile е канбан дъска за един човек и много AI агенти. Работи на твоя собствен компютър и е напълно безплатна. Добавяш проекти и всеки проект получава лидер и малък екип. Чатиш с лидера, малко като в Discord, и описваш идея; лидерът я превръща в карти и план, после чака да натиснеш Давай. Екипът минава през картите по приоритет, като използва прост команден ред, направен за езикови модели. Преди нещо да се върне при теб, AI тестер следва стъпките в копие на приложението и прикрепя снимка на екрана. Готовата работа пристига в твоята купчинка с променените файлове и разликата. Приемаш я или оставяш коментар, и екипът се събужда и опитва пак. Само ти можеш да преместиш карта в Готово.","Един ден с AI-gile, приблизително. Вечерта оставяш няколко коментара: този бутон е на грешно място, този списък трябва да е подреден, можем ли да имаме тъмен режим. Лягаш си. Агентите четат коментарите, правят промените, тестват ги и ти ги връщат. Ако За правене се изпразни, нощната стража го допълва от backlog с карти, които не искат отговор от теб. Сутринта има една кратка купчинка: няколко въпроса и няколко неща за изпробване, всяко със стъпки, които може да следва един сънлив човек, и със снимка на екрана как работи. Кликваш, приемаш добрите и връщаш останалите. Брояч на токени показва какво е изразходвано, а Режим без токени е за оскъдните седмици. После закусваш, с което агентите още не могат да помогнат.","Първо, какво AI-gile не е. Не е стартъп, не се продава и никой не събира данните ти. Безплатна дъска е, която работи на твоя компютър, без акаунти, без тракери и без бисквитки. Какво е: едно подредено място да видиш всички проекти с AI кодиране наведнъж, с екип от агенти, който върши картите, и ти, който взимаш решенията. Слива сродните карти, оправя объркани заглавия и следи колко компактен остава кодът. Говори около 120 езика, от нидерландски и фламандски до пиратски и клингонски. Приятелите могат да си пишат, лично и шифровано. Направена е от Рич и много търпеливи агенти, най-вече като използват самата нея. В затворена пре-алфа е, така че на места е грапава. Ако ти звучи забавно, попитай любезно и може да влезеш рано."]}],"quips":{"1":"Една дума. Смело. Може би твърде смело.","3":"Три думи. Вече по-честно от повечето страници на продукти.","8":"Осем думи. Пак по-кратко от стендъп.","21":"Дължините са story points, между другото. Разбира се, че са.","55":"Петдесет и пет думи. Две карти се довършиха, докато четеше това.","144":"Това е дългата. Няма 233. Агентите си легнаха."}},"timeline":{"first-idea.name":"Първата идея","first-idea.line":"Най-първият разговор, преди да съществува и един ред код.","first-board.name":"Първата дъска","first-board.line":"Дъска, която следи собственото си изграждане: карти, колони, дърпане и пускане, проекти.","team-roles.name":"Екип и роли","team-roles.line":"Профили на агенти, шаблони за екипи, пространства и кой какво прави.","install.name":"Инсталиране и версии","install.line":"Zip, който приятел може да инсталира, самообновяване, канали и връщане назад.","usage-saver.name":"Спестяване на ресурси","usage-saver.line":"Мери колко струват пусканията, дръж кода компактен, пази лимита си.","friends.name":"Приятели и споделяне","friends.line":"Лични съобщения, шифровано реле, покани, роли и споделени проекти.","languages.name":"Езици","languages.line":"Всеки екранен текст в езиков файл, първо нидерландски и фламандски.","ai-tester.name":"AI тестер","ai-tester.line":"Тестер проверява всяко предаване първо и показва какво е видял.","website.name":"Уебсайтът","website.line":"aigile.lol, тийзърът и тази времева линия.","streaming.name":"Чат и стрийминг","streaming.line":"Discord, Twitch, OBS, режим за стриймъри, GIF-ове и емоджита.","no-ai.name":"Версия без AI","no-ai.line":"Дъска за хора, които кодират без AI, и публични дъски.","night-watch.name":"Нощна стража","night-watch.line":"Пазач и Scrum Master държат екипите на задачата, докато спиш.","p-more.name":"Всичко останало","p-more.line":"По-малки идеи, които още чакат реда си.","p-android.name":"Телефон и Android","p-android.line":"Стигай до дъската си от телефона, после и с родно Android приложение.","p-release.name":"Алфа и нататък","p-release.line":"Затворена алфа, живият сайт, после бета.","p-languages.name":"Още езици","p-languages.line":"130 езика и режим на потапяне за учещите.","p-engines.name":"Още AI двигатели","p-engines.line":"Избери Claude, Codex, Gemini, Copilot или Cursor за всеки агент.","p-pro.name":"Професионална практика","p-pro.line":"Етикети за риск, врати за сливане, карти за инциденти и предпазни огради.","p-self.name":"Грижа за теб","p-self.line":"Режим на умора, напомняния за грижа за себе си и 4:20.","p-servers.name":"Сървъри и мащаб","p-servers.line":"Глобални настройки на сървъра, роли и планиране за растеж.","p-livestream.name":"Допълнения за стрийминг","p-livestream.line":"Twitch чат, собствени емоджита и публичен жив изглед."},"words":{"button":"📖 Професионален жаргон","h":"📖 Обяснени думи","intro":"Безплатно обучение на прост език: всяка дума, която срещаш, от първата идея до услуга, на която хората разчитат, с Agile, изграждане, поддържане на сигурност и работа с AI по пътя.","search":"Търси дума…","none":"Няма дума, която да съвпада.","close":"Затвори","count":{"one":"{count} дума","other":"{count} думи"},"groups":[{"id":"idea","name":"💡 Идея и проучване"},{"id":"plan","name":"🗺️ Планиране на работата"},{"id":"agile","name":"🔁 Гъвкави начини на работа"},{"id":"build","name":"🛠️ Създаване"},{"id":"test","name":"🧪 Тестване и качество"},{"id":"change","name":"🔀 Безопасни промени"},{"id":"run","name":"🛎️ Поддържане на услуга"},{"id":"sec","name":"🔒 Сигурност и поверителност"},{"id":"ai","name":"🤖 Работа с AI"},{"id":"money","name":"💰 Пари и лицензи"}],"list":[{"id":"discovery","g":"idea","word":"Проучване (Discovery)","text":"Ранният етап, в който откриваш кой проблем си струва да се реши и за кого, преди да се започне да се строи каквото и да е.","also":["фаза на проучване","discovery phase"]},{"id":"problemstmt","g":"idea","word":"Описание на проблема","text":"Едно-две изречения за това кой има проблем, какъв е той и защо е важен, за да се стремят всички към едно и също.","also":["описания на проблема","problem statement","problem statements"]},{"id":"user","g":"idea","word":"Потребител","text":"Човек, който използва това, което създаваш. Работата е заради неговите нужди.","also":["потребители","user","users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Заинтересована страна (Stakeholder)","text":"Всеки, който държи на резултата или е засегнат от него, като хората, които плащат за работата, я ползват или я поддържат.","also":["заинтересовани страни","stakeholders"]},{"id":"persona","g":"idea","word":"Персона (Persona)","text":"Измислен, но реалистичен човек, който представя един вид потребители, та екипът да може да попита „Ще е ли лесно това за Сам?“","also":["персони","personas"]},{"id":"userresearch","g":"idea","word":"Проучване на потребителите","text":"Разговор с истински хора и наблюдение на тях, за да разбереш от какво имат нужда, вместо да гадаеш.","also":["интервюта с потребители","user research","user interviews"]},{"id":"journey","g":"idea","word":"Пътят на потребителя (User journey)","text":"Стъпките, през които човек минава, за да свърши нещо, от първото чуване до края, и извън твоя продукт. Като го нарисуваш, се вижда къде заседават.","also":["пътища на потребителя","път на клиента","user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"Болка (Pain point)","text":"Нещо, което днес дразни хората или ги бави. Добрите продукти премахват такива болки.","also":["болки","pain points"]},{"id":"assumption","g":"idea","word":"Предположение","text":"Нещо, в което вярваш, но още не е проверено. Като запишеш предположенията, виждаш какво да тестваш първо.","also":["предположения","assumption","assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Хипотеза","text":"Най-доброто ти предположение, което смяташ да провериш, заедно с очакваното, например „хората ще се регистрират, ако първият месец е безплатен“.","also":["хипотези","hypothesis","hypotheses"]},{"id":"experiment","g":"idea","word":"Експеримент","text":"Малък планиран опит да разбереш дали идея работи, преди да заложиш много на нея.","also":["експерименти","experiment","experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Доказателство за концепцията (PoC)","text":"Бърз груб опит да се види дали идеята изобщо може да проработи. Обикновено се изхвърля, щом получиш отговор.","also":["PoC","proof of concept","доказателство на концепцията"]},{"id":"prototype","g":"idea","word":"Прототип","text":"Ранен модел на продукта, често с картинки, по които се кликва, за да изпробваш идеята върху хора, преди да я построиш както трябва.","also":["прототипи","prototype","prototypes"]},{"id":"wireframe","g":"idea","word":"Скица на екран (Wireframe)","text":"Проста скица на екран, която показва къде какво стои, без цветове и истинско съдържание.","also":["wireframe","wireframes","уайърфрейм"]},{"id":"mockup","g":"idea","word":"Макет (Mockup)","text":"Подробна картина как ще изглежда екранът, с истински цветове и текст, но още нищо не работи.","also":["макети","mockup","mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Бизнес обосновка (Business case)","text":"Причините да се прави един проект: колко струва, какво носи или спестява и какви са рисковете.","also":["бизнес обосновки","business case","business cases"]},{"id":"feasibility","g":"idea","word":"Осъществимост","text":"Дали нещо наистина може да се построи и поддържа с времето, парите и уменията, които имаш.","also":["осъществим","feasibility"]},{"id":"outcome","g":"idea","word":"Резултат за хората (Outcome)","text":"Промяната, която искаш за хората, например по-малко пропуснати часове при лекар. Тя е по-важна от това колко неща са построени.","also":["резултати","outcome","outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Продукция (Output)","text":"Нещо, което екипът прави, като нов екран или справка. Фактът, че е направено, не значи автоматично, че помага на някого.","also":["output","outputs","произведено"],"noTip":1},{"id":"successmetric","g":"idea","word":"Показател за успех","text":"Число, което показва дали работата е постигнала целта си, например повече хора, които завършват поръчката си.","also":["показатели за успех","success metric","success metrics"]},{"id":"kpi","g":"idea","word":"Ключов показател за ефективност (KPI)","text":"Важно число, което следиш, за да видиш дали нещата вървят добре, например регистрации на седмица.","also":["KPI","KPIs","key performance indicator","ключови показатели"]},{"id":"okr","g":"idea","word":"Цели и ключови резултати (OKR)","text":"Начин за поставяне на цели: целта казва какво искаш, а няколко ключови резултата са числата, които показват, че е постигната.","also":["OKR","OKRs","objectives and key results"]},{"id":"product","g":"plan","word":"Продукт","text":"Нещото, което се строи и поддържа за потребителите си, като приложение, уебсайт или инструмент.","also":["продукти","product","products"],"noTip":1},{"id":"vision","g":"plan","word":"Визия за продукта","text":"Кратко описание на кого помага продуктът и накъде се движи в дългосрочен план.","also":["декларация за визия","vision statement","product vision"]},{"id":"po","g":"plan","word":"Собственик на продукта (PO)","text":"Човекът, който решава какво да се строи и в какъв ред, така че екипът винаги да работи по най-важното. В AI-gile това си ти.","also":["PO","product owner","product owners","продуктов собственик"]},{"id":"pm","g":"plan","word":"Продуктов мениджър (PM)","text":"Човекът, който се грижи за посоката на продукта: кои проблеми решава, за кого и защо. PM може да значи и ръководител на проект, така че провери кое от двете.","also":["продуктови мениджъри","product manager","product managers"]},{"id":"projmgr","g":"plan","word":"Ръководител на проект","text":"Човекът, който държи проекта в срока и бюджета, като следи кой какво прави и до кога.","also":["ръководители на проекти","project manager","project managers","проектен мениджър"]},{"id":"roadmap","g":"plan","word":"Пътна карта (Roadmap)","text":"Груб план какво предстои през следващите месеци, по ред. Показва посока, а не точни дати, и се променя, докато учиш.","also":["пътни карти","roadmap","roadmaps"]},{"id":"milestone","g":"plan","word":"Важен етап (Milestone)","text":"Момент в проекта, който си заслужава да се отбележи, например „първата версия е пусната“ или „100 потребители“.","also":["етапи","milestone","milestones","ключов момент"]},{"id":"mvp","g":"plan","word":"Минимален жизнеспособен продукт (MVP)","text":"Най-малката версия на продукта, която все пак е полезна на истински хора, за да можеш да учиш от тях още отрано.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Изискване","text":"Нещо, което готовият продукт трябва да прави или да бъде.","also":["изисквания","requirement","requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Обхват (Scope)","text":"Какво е включено в работата и, също толкова важно, какво не е.","also":["в обхвата","извън обхвата","in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Раздуване на обхвата (Scope creep)","text":"Когато към работата се добавя все повече и повече, малко по малко, без някой да се е съгласил с допълнителното време или цена, и тя така и не свършва.","also":["feature creep","пълзящи изисквания"]},{"id":"feature","g":"plan","word":"Функция (Feature)","text":"Едно нещо, което продуктът може да прави за хората, например „нулирай паролата си“.","also":["функции","възможност","feature","features"],"noTip":1},{"id":"epic","g":"plan","word":"Епик (Epic)","text":"Голяма част от работата, твърде голяма за наведнъж, затова се разделя на по-малки карти.","also":["епици","epic","epics"]},{"id":"story","g":"plan","word":"Потребителска история (User story)","text":"Малка част от работата, описана от гледната точка на потребителя: „Като купувач искам да запазя кошницата си, за да довърша по-късно.“ Тя започва разговор какво да се строи.","also":["потребителски истории","user story","user stories"]},{"id":"ac","g":"plan","word":"Критерии за приемане (AC)","text":"Проверките, които една карта трябва да премине, за да се счита за готова, уговорени преди да започне работата, например „кошницата още е там, след като изляза и вляза пак“.","also":["AC","acceptance criteria","критерии за приемане"]},{"id":"task","g":"plan","word":"Задача","text":"Една отделна работа за вършене, често малка стъпка от по-голяма история.","also":["задачи","task","tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Тикет (Ticket)","text":"Друга дума за карта: една част от работата или едно искане, следено от началото до края.","also":["тикети","ticket","tickets","заявка"]},{"id":"priority","g":"plan","word":"Приоритет","text":"Колко е важно или спешно нещо в сравнение с всичко останало, за да се върши първо най-важното.","also":["приоритети","priority","priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Подреждане по приоритет","text":"Подреждане на работата по важност. Често се ползва MoSCoW: Трябва (Must), Би трябвало (Should), Може (Could), Не този път (Won’t).","also":["приоритизиране","prioritisation","MoSCoW"]},{"id":"estimate","g":"plan","word":"Оценка","text":"Най-доброто предположение колко голяма е една работа или колко време ще отнеме. Това е предположение, а не обещание.","also":["оценки","оценяване","estimate","estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Точки за история (Story points)","text":"Начин да познаеш размера на работата, като сравняваш картите една с друга („около два пъти по-голяма от онази“), вместо в часове. Не са за сравняване на екипи.","also":["story point","story points","сторипойнтове"]},{"id":"tshirt","g":"plan","word":"Размери като на тениски (T-shirt sizing)","text":"Оценка на размера на работата като S, M, L или XL. Бързо е и стига за ранно планиране.","also":["t-shirt sizes","размери S M L"]},{"id":"poker","g":"plan","word":"Планиращ покер (Planning poker)","text":"Игра за оценяване: всички показват карта с размер едновременно, после тези с най-високата и най-ниската оценка обясняват защо.","also":["Scrum poker","покер за оценка"]},{"id":"dependency","g":"plan","word":"Зависимост","text":"Когато една работа не може да започне или да свърши, докато не го направи друга.","also":["зависимости","dependency","dependencies"]},{"id":"blocker","g":"plan","word":"Спънка (Blocker)","text":"Всичко, което в момента спира работата да върви напред, като липсващ отговор или развален инструмент.","also":["спънки","блокер","blocker","blockers"]},{"id":"deadline","g":"plan","word":"Краен срок","text":"Датата, до която нещо трябва да е завършено.","also":["крайни срокове","deadline","deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Резултат за предаване (Deliverable)","text":"Нещо конкретно, което работата създава и предава, като работеща страница или справка.","also":["deliverable","deliverables","предаваем резултат"]},{"id":"forecast","g":"plan","word":"Прогноза","text":"Предвиждане какво е вероятно да се случи, например кога работата ще е готова, въз основа на това, което знаеш досега.","also":["прогнози","forecast","forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Показател (Metric)","text":"Всичко, което измерваш и следиш във времето, като посещенията на страница или колко време отнема една поправка.","also":["показатели","метрика","metric","metrics"]},{"id":"feedback","g":"plan","word":"Обратна връзка","text":"Какво ти казват хората за работата ти, хубаво и лошо. Получаването ѝ рано и често е същината на Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Чакащият списък с идеи и работа, още непланирани, като най-важното е най-горе. Нищо оттам не се работи, докато не се премести в „За изпълнение“."},{"id":"sprint","g":"agile","word":"Спринт","text":"Кратък, фиксиран период работа (често една или две седмици, никога повече от месец) с цел и уговорен набор от карти за довършване.","also":["спринт","спринта","спринтове","спринтовете","sprint","sprints"]},{"id":"standup","g":"agile","word":"Стендъп","text":"Бърза ежедневна среща: какво е правил всеки от екипа, какво прави после и какво го спира. В Scrum се нарича дневен скръм.","also":["standup","stand-ups","daily scrum","daily stand-up","дневен скръм","стендъп"]},{"id":"kanban","g":"agile","word":"Канбан","text":"Начин на работа, при който картите се движат през колоните на едно табло (като За изпълнение, В процес, Готово), а екипът ограничава колко е в процес наведнъж, така че работата да не спира."},{"id":"wip","g":"agile","word":"WIP лимит","text":"WIP значи work in progress (работа в процес). WIP лимитът е най-много карти, които една колона трябва да държи наведнъж, за да довършва екипът нещата, преди да започне още.","also":["WIP","wip лимит"]},{"id":"dod","g":"agile","word":"Определение за „Свършено“","text":"Краткият списък на екипа какво значи „завършено“, например тествано и обяснено, преди картата да ти бъде предадена. Близнакът му, Определението за „Готово за старт“, казва кога картата е достатъчно ясна, за да се започне.","also":["Definition of Ready","DoD","DoR","определение за готовност"]},{"id":"retro","g":"agile","word":"Ретро","text":"Редовен поглед назад как работи екипът, за да се уговорят едно-две неща за подобряване следващия път. Съкращение от ретроспекция. В AI-gile ретроспекцията предлага промяна в начина на работа на екипа и ти казваш „Давай“ или „Още не“.","also":["ретроспектива","retro","retrospective"]},{"id":"swarm","g":"agile","word":"Рояк","text":"Всички на работа: много хора зарязват другата си работа, за да оправят заедно едно спешно нещо, докато се уреди. В AI-gile всеки екип помага на един проект, а другите проекти междувременно чакат.","also":["swarm","swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"В Scrum човекът, който помага на екипа да работи добре: разчиства каквото го спира, грижи се срещите да не се отклоняват и учи на добри навици, без да командва никого. В AI-gile Lead Scrum Master забелязва заседнали карти, побутва екипите и ти напомня какво чака, във всички проекти.","also":["Lead Scrum Master","скръм мастър"]},{"id":"agile","g":"agile","word":"Agile (гъвкав подход)","text":"Начин на работа на малки стъпки: строиш малко, показваш често реални резултати, учиш от думите на хората и сменяш плана в движение, вместо да планираш всичко отнапред.","also":["Agile development","agile ways of working","гъвкава разработка","Аджайл"]},{"id":"manifesto","g":"agile","word":"Манифест на Agile","text":"Кратка декларация, написана през 2001 г. от създатели на софтуер. Поставя хората, работещите резултати, тясното сътрудничество с клиентите и отзивчивостта към промяна пред тежките планове и документи.","also":["Agile Manifesto","Manifesto for Agile Software Development","Agile манифест"]},{"id":"waterfall","g":"agile","word":"Водопад (Waterfall)","text":"По-старият начин на работа: планираш всичко, после го строиш цялото, после го тестваш цялото, етап след етап. Късните промени са трудни и скъпи.","also":["waterfall model","модел водопад"]},{"id":"iteration","g":"agile","word":"Итерация","text":"Един кръг на построяване на нещо, проверка и подобряване. Agile работата е верига от такива, а спринтът е един вид итерация.","also":["итерации","iteration","iterations"]},{"id":"increment","g":"agile","word":"Инкремент","text":"Ново работещо парче, добавено към продукта в рамките на спринт или кръг работа, което пасва на вече съществуващото.","also":["инкременти","increment","increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"Популярен Agile начин на работа: малък екип работи на кратки спринтове към цел, със зададени роли и няколко редовни срещи за планиране, проверка и подобрение."},{"id":"scrumteam","g":"agile","word":"Scrum екип","text":"Малката група, която върши работата в Scrum: собственик на продукта, Scrum Master и разработчиците.","also":["Scrum екипи","Scrum team","Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Събития в Scrum","text":"Редовните срещи в Scrum: планиране на спринта, дневният скръм, прегледът на спринта и ретроспекцията. Мнозина ги наричат церемонии.","also":["церемонии","Scrum церемонии","ceremonies","Scrum ceremonies","Scrum events"]},{"id":"sprintplan","g":"agile","word":"Планиране на спринта","text":"Срещата в началото на спринта, на която екипът се разбира защо е важен спринтът, кои карти ще поеме и как да започне.","also":["среща за планиране","sprint planning","planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Цел на спринта","text":"Едно изречение за това за какво е спринтът. Дребните задачи могат да се променят по пътя, стига целта да е постигната.","also":["цели на спринта","sprint goal","sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Sprint backlog (списък на спринта)","text":"Картите, избрани за текущия спринт, заедно с плана на екипа как да ги свърши.","also":["sprint backlogs","списък на спринта"]},{"id":"productbacklog","g":"agile","word":"Product backlog (списък на продукта)","text":"Пълният подреден списък с всичко, което може да се построи за продукта, като най-важното е най-горе. Променя се, докато учиш.","also":["product backlogs","списък на продукта"]},{"id":"productgoal","g":"agile","word":"Цел на продукта","text":"По-големият резултат, към който върви продуктът и който помага на екипа да избира какво да прави по-нататък.","also":["цели на продукта","product goal","product goals"]},{"id":"refinement","g":"agile","word":"Изчистване на backlog (Refinement)","text":"Редовно преглеждане на backlog, за да се подредят, разделят и допълнят картите с подробности, така че да са готови за вземане. Наричат го още backlog grooming.","also":["backlog grooming","refinement","подготовка на backlog"]},{"id":"sprintreview","g":"agile","word":"Преглед на спринта","text":"Среща в края на спринта, на която екипът показва какво е завършил и чува мнението на хората, за да реши какво следва.","also":["прегледи на спринта","sprint review","sprint reviews"]},{"id":"demo","g":"agile","word":"Демо","text":"Показване на готова работа как действа, на живо, пред хората, които са я поискали.","also":["демота","demo","demos","демонстрация"],"noTip":1},{"id":"timebox","g":"agile","word":"Времева рамка (Timebox)","text":"Фиксирано количество време за нещо. Когато изтече, спираш, дори и да не е всичко готово.","also":["timeboxed","timeboxes","ограничено във времето"]},{"id":"velocity","g":"agile","word":"Скорост на екипа (Velocity)","text":"Колко работа един екип обикновено завършва за спринт; ползва се, за да се планира колко да се поеме следващия път. Не е оценка за това колко усилено се работи.","also":["team velocity","velocity"]},{"id":"capacity","g":"agile","word":"Капацитет","text":"Колко работа екипът може да поеме за даден период, след като се извадят отпуските и другите задачи.","noTip":1},{"id":"burndown","g":"agile","word":"Диаграма на изгарянето (Burndown)","text":"Диаграма на оставащата работа в спринта, която слиза ден след ден. Ако линията стои равна, нещо е заседнало.","also":["burndown","burn-down chart","burndown chart"]},{"id":"burnup","g":"agile","word":"Диаграма на натрупването (Burnup)","text":"Диаграма на завършената работа, която се качва във времето, до общата планирана, за да видиш кога ще стигнеш.","also":["burnup","burn-up chart","burnup chart"]},{"id":"kanbanboard","g":"agile","word":"Канбан табло","text":"Самото табло: колона за всеки етап на работата, с карти, които се движат напред.","also":["Kanban board","Kanban boards","канбан дъска"]},{"id":"pullsys","g":"agile","word":"Система на дърпане (Pull system)","text":"Начин на работа, при който нова работа започва само когато някой има място да я поеме, вместо да му се натрупва върху препълнена чиния.","also":["pull system","pull-based","дърпане"]},{"id":"flow","g":"agile","word":"Поток (Flow)","text":"Колко гладко работата се движи по таблото. Добрият поток значи, че картите вървят, вместо да се трупат.","also":["flow","flow of work","поток на работата"],"noTip":1},{"id":"leadtime","g":"agile","word":"Общо време (Lead time)","text":"Колко време минава от искането на нещо до завършването му.","also":["lead time","lead times","време до изпълнение"]},{"id":"cycletime","g":"agile","word":"Време на работа (Cycle time)","text":"Колко време отнема една карта от момента, в който наистина се започне работа по нея, до завършването ѝ.","also":["cycle time","cycle times","цикъл на работа"]},{"id":"throughput","g":"agile","word":"Пропускателна способност (Throughput)","text":"Колко карти се завършват за седмица или за друго зададено време.","also":["throughput","throughput rate","производителност"]},{"id":"bottleneck","g":"agile","word":"Тясно място (Bottleneck)","text":"Единственият етап, където работата се трупа и забавя всичко след него, като тясното гърло на бутилка.","also":["bottleneck","bottlenecks","пречка в потока"]},{"id":"swimlane","g":"agile","word":"Лента (Swimlane)","text":"Ред през таблото, който групира карти от един вид, като спешна работа или картите на един екип.","also":["swimlane","swimlanes","swim lane","ленти"]},{"id":"lean","g":"agile","word":"Lean (стегнат подход)","text":"Начин на работа, който премахва загубите (всичко, което не помага на клиента) и държи работата в движение."},{"id":"waste","g":"agile","word":"Загуба (Waste)","text":"В Lean всичко, което взима усилия, но не помага на клиента, като чакане, преработване или строене на неща, които никой не ползва.","noTip":1},{"id":"kaizen","g":"agile","word":"Непрекъснато подобрение","text":"Да ставаш малко по-добър през цялото време чрез малки редовни промени и да проверяваш дали са помогнали. Ретроспекциите са един от начините. Наричат го още кайдзен.","also":["kaizen","кайдзен","continuous improvement"]},{"id":"selforg","g":"agile","word":"Самоорганизиращ се екип","text":"Екип, който сам решава как да върши работата, вместо да му се казва стъпка по стъпка.","also":["самоорганизиращи се","self-organising","self-organising team","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Мултифункционален екип","text":"Екип, който има всички умения, нужни, за да завърши работата сам, като дизайн, изграждане и тестване.","also":["cross-functional","cross-functional team","междуфункционален екип"]},{"id":"spike","g":"agile","word":"Проучвателна задача (Spike)","text":"Кратко проучване с ограничено време, което отговаря на въпрос, преди да се захванеш с истинската работа.","also":["spike","spikes","спайк"]},{"id":"rework","g":"agile","word":"Преработване (Rework)","text":"Вършене на работа отново, защото първия път не е била наред.","also":["rework","reworked","поправяне наново"]},{"id":"safe","g":"agile","word":"Мащабиран Agile (SAFe)","text":"Начини да се ползва Agile в много екипи на голяма организация. SAFe (Scaled Agile Framework) е един добре известен пример.","also":["scaled Agile","Scaled Agile"]},{"id":"repo","g":"build","word":"Хранилище","text":"Папката на проекта с кода и пълната му история от комити. Може да е на твоя компютър, в GitHub или и на двете места.","also":["хранилище","хранилища","репо","repo","repository"]},{"id":"branch","g":"build","word":"Клон","text":"Отделна линия работа в кода, за да се правят промени, без да се пипа основната версия.","also":["клон","клона","клонове","клоновете","branch","branches"]},{"id":"commit","g":"build","word":"Къмит","text":"Запазена снимка на кода с кратка бележка какво е променено. Винаги можеш да се върнеш към някой.","also":["къмит","къмита","къмити","къмитите","commit","commits"]},{"id":"push","g":"build","word":"Push","text":"Изпращане на запазените ти снимки (комити) от този компютър към споделеното копие онлайн, като GitHub, за да са запазени и другите да могат да ги вземат."},{"id":"merge","g":"build","word":"Сливане","text":"Обединяване на промените от един клон в друг, обикновено обратно в основната версия."},{"id":"pr","g":"build","word":"Pull request","text":"Искане промените на един клон да бъдат проверени и слети в основната версия. Някои сайтове го наричат merge request.","also":["PR","PRs","merge request","заявка за сливане"]},{"id":"refactor","g":"build","word":"Рефакториране","text":"Подреждане на кода, без да се променя какво прави: по-малки файлове, по-ясни имена, по-малко повторения."},{"id":"bug","g":"build","word":"Бъг","text":"Нещо, което не работи както трябва.","also":["бъг","бъга","бъгове","бъговете","bug","bugs"]},{"id":"peerreview","g":"build","word":"Колегиална проверка","text":"Втора двойка очи: някой друг, не авторът, проверява работата, преди да стигне до теб, та да минат по-малко грешки. В AI-gile друг AI проверява всяка карта.","also":["преглед на кода","peer review","code review"]},{"id":"code","g":"build","word":"Код","text":"Написаните инструкции, които казват на компютъра какво да прави. Наричат се още изходен код.","also":["изходен код","source code","code"],"noTip":1},{"id":"proglang","g":"build","word":"Език за програмиране","text":"Език за писане на код, като JavaScript, Python или Java. Различните са подходящи за различни работи.","also":["езици за програмиране","programming language","programming languages"]},{"id":"developer","g":"build","word":"Разработчик (dev)","text":"Човек, който пише и променя код. Наричат го още програмист или софтуерен инженер.","also":["разработчици","програмист","програмисти","developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Софтуер","text":"Програмите, които работят на компютри и телефони, за разлика от самите машини (хардуера).","noTip":1},{"id":"app","g":"build","word":"Приложение (App)","text":"Програма, която хората използват, за да свършат нещо, на телефон, компютър или в уеб браузър.","also":["приложения","app","apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Уеб приложение","text":"Приложение, което работи в уеб браузър, така че не е нужно нищо да се инсталира.","also":["уеб приложения","web app","web apps","web application"]},{"id":"frontend","g":"build","word":"Front end (лицевата част)","text":"Частта от приложението, която виждаш и върху която кликаш: екраните, бутоните и думите, често в браузъра ти.","also":["front-end","frontend","лицева част"]},{"id":"backend","g":"build","word":"Back end (вътрешната част)","text":"Частта от приложението зад кулисите, която пази данните и върши работата, когато кликнеш нещо, например проверява паролата ти.","also":["back-end","backend","вътрешна част"]},{"id":"fullstack","g":"build","word":"Full stack (цялостна разработка)","text":"Работа и по лицевата, и по вътрешната част.","also":["full-stack","full stack"]},{"id":"ui","g":"build","word":"Потребителски интерфейс (UI)","text":"Това, което човек вижда и ползва на екрана: разположение, бутони, менюта и текст.","also":["UI","user interface","интерфейс"]},{"id":"ux","g":"build","word":"Потребителско преживяване (UX)","text":"Какво е усещането да ползваш нещо: лесно, ясно и приятно или объркващо и бавно.","also":["UX","user experience","удобство на ползване"]},{"id":"accessibility","g":"build","word":"Достъпност (a11y)","text":"Да се прави така, че всеки да може да ползва нещата, включително хора, които не виждат добре, не могат да ползват мишка или ползват екранен четец.","also":["a11y","accessibility"]},{"id":"responsive","g":"build","word":"Адаптивен дизайн","text":"Страниците да се побират и да работят добре на всеки размер екран, от телефон до голям монитор.","also":["responsive design","респонсив"]},{"id":"designsys","g":"build","word":"Дизайн система","text":"Общ набор от цветове, шрифтове, бутони и правила, та всеки екран да изглежда и да се държи по един и същ начин.","also":["дизайн системи","design system","design systems"]},{"id":"architecture","g":"build","word":"Архитектура","text":"Общият вид на една система: кои са основните ѝ части и как си говорят помежду си."},{"id":"database","g":"build","word":"База данни (DB)","text":"Подредено хранилище за информация, като много мощна електронна таблица, която приложението може да чете и променя.","also":["бази данни","database","databases","DB"]},{"id":"schema","g":"build","word":"Схема на базата данни","text":"Как е устроена една база данни: какви таблици с информация има и какво влиза във всяка.","also":["schema","database schema","схема"]},{"id":"sql","g":"build","word":"SQL","text":"Съкращение от structured query language (структуриран език за заявки): езикът, с който се иска информация от много бази данни или се променя в тях.","also":["Structured Query Language","език за заявки"]},{"id":"data","g":"build","word":"Данни","text":"Информация, пазена от компютър, като имена, поръчки или настройки.","also":["data","dataset","datasets","набор от данни"],"noTip":1},{"id":"server","g":"build","word":"Сървър","text":"Компютър, който е винаги включен и отговаря на заявки от други компютри, например изпраща уеб страница, когато я посетиш.","also":["сървъри","server","servers"]},{"id":"client","g":"build","word":"Клиент","text":"Страната, която иска нещо, обикновено браузърът или приложението ти, като говори със сървър. В бизнеса думата значи и просто купувач.","also":["клиенти","client","clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Съкращение от application programming interface: готово меню от заявки, които една програма може да отправя към друга, например да поиска от метеорологична услуга днешната прогноза.","also":["APIs","application programming interface","програмен интерфейс"]},{"id":"endpoint","g":"build","word":"Крайна точка (Endpoint)","text":"Една позиция от менюто на API: уеб адрес, на който една програма може да се обади, за да вземе или изпрати нещо.","also":["endpoint","endpoints","крайни точки"]},{"id":"integration","g":"build","word":"Интеграция","text":"Свързване на две системи, за да работят заедно, например магазинът ти да праща поръчките към счетоводния ти софтуер.","also":["интеграции","integration","integrations"]},{"id":"webhook","g":"build","word":"Уебхук (Webhook)","text":"Съобщение, което една система сама изпраща на друга в мига, в който нещо се случи, например „плащането е получено“.","also":["webhook","webhooks","уебхук","уебхукове"]},{"id":"library","g":"build","word":"Библиотека","text":"Готов код, написан от някой друг, който можеш да използваш повторно, вместо да го пишеш от нулата.","also":["библиотеки","library","libraries"],"noTip":1},{"id":"framework","g":"build","word":"Фреймуърк (Framework)","text":"Готова структура за изграждане на приложение, която определя голяма част от подредбата на кода, като скелет на къща, който ти запълваш.","also":["framework","frameworks","рамка"]},{"id":"sdk","g":"build","word":"Комплект за разработка (SDK)","text":"Кутия с инструменти, код и примери за писане на софтуер за една платформа или услуга.","also":["SDK","SDKs","software development kit"]},{"id":"softdep","g":"build","word":"Софтуерна зависимост","text":"Библиотека или инструмент, от които кодът ти се нуждае, за да работи. Важно е да се обновяват за безопасност.","also":["софтуерни зависимости","software dependency","software dependencies"]},{"id":"package","g":"build","word":"Пакет","text":"Пакет с готов код, който можеш да инсталираш и да ползваш в проект.","also":["пакети","package","packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Мениджър на пакети","text":"Инструмент, който сваля и обновява пакетите, от които зависи кодът ти. npm е един от най-разпространените.","also":["мениджъри на пакети","package manager","package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"Най-широко използваният инструмент за пазене на историята на промените в кода, във вид на комити и клонове."},{"id":"github","g":"build","word":"GitHub","text":"Уебсайт, който пази Git хранилища онлайн, та екипите да споделят код, да преглеждат промени и да следят работата."},{"id":"vcs","g":"build","word":"Контрол на версиите","text":"Пазене на пълна история на всяка промяна във файловете, за да виждаш кой какво е променил и да можеш да се върнеш назад. Git го прави.","also":["контрол на изходния код","version control","source control","version control system"]},{"id":"clone","g":"build","word":"Клониране (Clone)","text":"Правене на собствено пълно копие на хранилище, с историята му, на твоя компютър.","also":["клонирам","clone","cloned","cloning"]},{"id":"pull","g":"build","word":"Дърпане (Pull)","text":"Сваляне на най-новите комити от споделеното копие (например GitHub) на твоя компютър. Обратното на push.","also":["git pull","pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Основен клон (Main branch)","text":"Официалната версия на кода, от която тръгват всички, често наричана main или master.","also":["master branch","main branch","главен клон"]},{"id":"conflict","g":"build","word":"Конфликт при сливане","text":"Когато две промени засягат едни и същи редове по различен начин, компютърът не може да ги обедини и човек трябва да избере.","also":["конфликти при сливане","merge conflict","merge conflicts"]},{"id":"diff","g":"build","word":"Разлика (Diff)","text":"Изглед, който показва точно какво се е променило между две версии: добавените и махнатите редове.","also":["diff","diffs","разлики"]},{"id":"fork","g":"build","word":"Разклонение (Fork)","text":"Твое собствено копие на чуждо хранилище, което можеш да променяш, без да засягаш оригинала.","also":["fork","forks","forked","форк"]},{"id":"script","g":"build","word":"Скрипт","text":"Кратка програма, която сама върши една работа, като подреждане на файлове или стартиране на приложението.","also":["скриптове","script","scripts"],"noTip":1},{"id":"build","g":"build","word":"Изграждане (Build)","text":"Превръщане на кода в нещо, готово за пускане, или самият готов за пускане резултат.","also":["build","builds","билд","билдове"],"noTip":1},{"id":"compile","g":"build","word":"Компилиране","text":"Превеждане на написания от хора код във вид, който компютърът може да изпълни директно.","also":["compile","compiler","компилатор"]},{"id":"cli","g":"build","word":"Команден ред (CLI)","text":"Текстов прозорец, в който пишеш инструкции на компютъра, вместо да кликаш. Наричат го още терминал.","also":["command line","command-line","CLI","terminal","терминал"]},{"id":"config","g":"build","word":"Конфигурация (config)","text":"Настройките, които определят как се държи софтуерът, пазени отделно от кода, за да се сменят лесно.","also":["config","configuration","настройки"],"noTip":1},{"id":"envvar","g":"build","word":"Променлива на средата","text":"Настройка, подадена на програмата при стартиране, често за адреси или пароли, за да не са записани в кода.","also":["променливи на средата","environment variable","environment variables","env var"]},{"id":"debugging","g":"build","word":"Дебъгване (търсене на грешки)","text":"Издирване защо нещо не работи и поправянето му.","also":["дебъгване","debugging","debug","debugged"]},{"id":"pairing","g":"build","word":"Програмиране по двойки","text":"Двама души (или човек и AI) работят заедно върху един и същ код, единият пише, а другият проверява.","also":["pair programming","pairing","работа по двойки"]},{"id":"docs","g":"build","word":"Документация (docs)","text":"Писмени обяснения как работи нещо или как да се ползва.","also":["documentation","docs","документи"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"Първият файл за четене в хранилище: какво е проектът и как да се пусне.","also":["READMEs","прочети ме"]},{"id":"legacy","g":"build","word":"Остаряла система (Legacy)","text":"По-стара система, която още се ползва и трудно се променя, често защото малко хора още я разбират.","also":["остарели системи","legacy system","legacy systems","legacy code","наследен код"]},{"id":"techdebt","g":"build","word":"Технически дълг","text":"Пряки пътища, които спестяват време сега, но забавят по-късните промени, като заем, върху който се трупа лихва. Рефакторирането го изплаща.","also":["tech debt","technical debt","технически дългове"]},{"id":"test","g":"test","word":"Тест","text":"Проверка дали нещо работи както трябва. Някои тестове компютърът пуска сам при всяка промяна в кода; други са твоето изпробване на завършена карта, преди да я приемеш.","also":["тест","теста","тестове","тестовете","тестване","test","tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Съкращение от quality assurance (осигуряване на качеството): всичко, което се прави, за да е сигурно, че работата е наред, преди да излезе. В AI-gile това са автоматичните проверки: когато QA е червено, нещо е паднало и не може да излезе, докато не се поправи.","also":["проверки на качеството","осигуряване на качеството","quality checks"]},{"id":"testpile","g":"test","word":"Купчина за тестове","text":"Завършените карти, които чакат да ги пробваш, една след друга. Приеми една или я върни с бележка и идва следващата.","also":["купчини за тестове","test pile"]},{"id":"autotest","g":"test","word":"Автоматичен тест","text":"Проверка, която компютърът пуска сам при всяка промяна в кода, за да хване грешките рано.","also":["автоматични тестове","automated test","automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Ръчен тест","text":"Човек изпробва работата на ръка, за да види дали се държи както трябва.","also":["ръчни тестове","ръчно тестване","manual test","manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Модулен тест (Unit test)","text":"Малка автоматична проверка на едно мъничко парче код самостоятелно.","also":["unit test","unit tests","юнит тест"]},{"id":"integtest","g":"test","word":"Интеграционен тест","text":"Проверка, че няколко части работят добре заедно, а не само една по една.","also":["интеграционни тестове","integration test","integration tests"]},{"id":"endtoend","g":"test","word":"Тест от край до край (E2E)","text":"Тест, който действа като истински потребител от началото до края, например регистрира се, купува и плаща.","also":["E2E","end-to-end tests","end-to-end test"]},{"id":"uat","g":"test","word":"Приемателно тестване от потребители (UAT)","text":"Хората, поискали работата, я изпробват сами и казват дали прави каквото им трябва. Купчината за тестване в AI-gile е нейната версия на това.","also":["UAT","acceptance testing","приемателно тестване"]},{"id":"regression","g":"test","word":"Регресия","text":"Нещо, което е работело, но се е счупило след промяна. Регресионните тестове проверяват дали старите неща още работят.","also":["регресии","regression","regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Бърз пробен тест (Smoke test)","text":"Много бърза проверка дали основните неща изобщо работят, например веднага след пускане на промяна. Ако не мине, спираш и гледаш.","also":["smoke test","smoke tests","смоук тест"]},{"id":"exploratory","g":"test","word":"Изследователско тестване","text":"Свободно изпробване на продукта и човъркане в него по различни начини, за да се открият проблеми, които планираните проверки биха пропуснали.","also":["exploratory testing","exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Тестов случай","text":"Един записан сценарий за изпробване: стъпките и какво трябва да се случи.","also":["тестови случаи","test case","test cases"]},{"id":"coverage","g":"test","word":"Покритие на тестовете","text":"Каква част от кода се проверява от автоматични тестове. Повече обикновено е по-безопасно, но високото покритие само по себе си не доказва, че работи добре.","also":["покритие","test coverage","code coverage"]},{"id":"testdata","g":"test","word":"Тестови данни","text":"Измислена примерна информация, ползвана при тестване, за да не се разкриват личните данни на истински хора.","also":["test data","test fixtures"]},{"id":"edgecase","g":"test","word":"Граничен случай (Edge case)","text":"Необичайна ситуация на границата, като празна форма или име с апостроф, където нещата често се чупят.","also":["гранични случаи","edge case","edge cases"]},{"id":"happypath","g":"test","word":"Щастлив път (Happy path)","text":"Нормалният път, при който всичко върви добре. Доброто тестване изпробва и пътищата, при които нещо се обърква."},{"id":"perftest","g":"test","word":"Тестване на производителността","text":"Проверка колко бързо е нещо и колко добре се справя под натиск.","also":["performance testing","performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Натоварващо тестване","text":"Проверка как се справя една система, когато много хора я ползват едновременно.","also":["load testing","load test","load tests","тест на натоварването"]},{"id":"sectest","g":"test","word":"Тестване на сигурността","text":"Търсене на слабости, чрез които някой би могъл да злоупотреби със системата или да види това, което не бива.","also":["security testing","security test","security tests"]},{"id":"accesstest","g":"test","word":"Тестване на достъпността","text":"Проверка дали хора с различни възможности могат да ползват продукта, включително с екранен четец или само с клавиатура.","also":["accessibility testing","accessibility test"]},{"id":"linting","g":"test","word":"Линтване (Linting)","text":"Автоматична проверка, която открива вероятни грешки и немарлив стил в кода, като правописна проверка за програми.","also":["linting","linter","lint","линтер"]},{"id":"static","g":"test","word":"Статичен анализ","text":"Проверка на кода за проблеми чрез автоматичното му четене, без да се пуска.","also":["static analysis","static code analysis","статичен анализ на код"]},{"id":"flaky","g":"test","word":"Нестабилен тест (Flaky test)","text":"Тест, който понякога минава, а понякога пада без ясна причина, така че не може напълно да му се вярва.","also":["flaky test","flaky tests","мигащ тест"]},{"id":"repro","g":"test","word":"Възпроизвеждане (repro)","text":"Да накараш бъг да се случи отново нарочно, като следваш същите стъпки, за да може да се проучи и поправи. Записването на тези стъпки е най-полезната част от доклада за бъг.","also":["repro","reproduce","steps to reproduce","стъпки за възпроизвеждане"]},{"id":"severity","g":"test","word":"Сериозност (Severity)","text":"Колко лошо е въздействието на проблем, от дребно неудобство до спиране на всичко.","also":["severity","severity level","степен на сериозност"]},{"id":"deploy","g":"change","word":"Деплой","text":"Копиране на нова версия на софтуера на компютрите, които го изпълняват, като тестово копие или живата услуга."},{"id":"release","g":"change","word":"Версия","text":"Пакет завършена работа с име, който излиза на живо наведнъж, с кратки бележки какво се е променило. 🚀 Версии пише бележките от завършените карти.","also":["версии","релийз","release"]},{"id":"rollback","g":"change","word":"Връщане назад","text":"Връщане към последната работеща версия, когато новата създава проблеми. В AI-gile „Върни назад“ събира стъпките за отмяна, записани при всяка промяна, в един контролен списък.","also":["върни назад","rollback","roll back"]},{"id":"live","g":"change","word":"На живо","text":"Истинската версия, която хората ползват, за разлика от копие за пробване на неща. Разработчиците я наричат и продукция (production).","also":["продукция","продукционна среда","production","live"],"noTip":1},{"id":"change","g":"change","word":"Промяна","text":"Планирана промяна в нещо, на което хората разчитат, първо записана: какво, защо, рискът, кога и как да се отмени. Започни една с 🔀 Подай промяна.","also":["промени","заявка за промяна","change request"],"noTip":1},{"id":"risk","g":"change","word":"Риск","text":"Нещо, което може да се обърка, оценено по това колко е вероятно и колко лошо би било. ⚠️ Рискове ги държи в един списък, с най-високата оценка най-горе, всеки с дата за нов преглед.","also":["рискове","регистър на рисковете"]},{"id":"chgwin","g":"change","word":"Прозорец за промени","text":"Времето, когато промените могат да излизат на живо, например спокойна вечер във вторник. Извън прозорец карта за промяна не може да се завърши, освен ако не е спешна.","also":["прозорци за промени","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Последна проверка точно преди промяната да излезе: всеки човек, който трябва да одобри, казва „Давай“ или „Не“. Продължава само когато всички кажат „Давай“.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Одобрение","text":"Чакане на „да“, преди да започне работа. Карта, подадена от приятел, или промяна чака в ✅ Одобрения, докато не я одобриш или откажеш.","also":["одобрения","approval"]},{"id":"quiettime","g":"change","word":"Тихо време","text":"Период, като по време на пряко предаване, демо или през нощта, когато нищо не излиза. Екипите продължават да работят и да тестват, но пускането чака края. На други места се нарича замразяване на промените.","also":["тихи времена","замразяване на промените","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"Начин на работа, при който хората, които правят софтуера, и хората, които го поддържат, работят като един екип, с много автоматизация, така че промените да излизат често и безопасно."},{"id":"cicd","g":"change","word":"CI/CD (непрекъсната интеграция и доставка)","text":"Промените на всички се сливат често в основната версия и се проверяват автоматично всеки път (непрекъсната интеграция), така че софтуерът винаги е готов да излезе с натискането на бутон (непрекъсната доставка).","also":["CI/CD","CI","CD","continuous integration","continuous delivery","непрекъсната интеграция"]},{"id":"contdeploy","g":"change","word":"Непрекъснато внедряване","text":"Крачка отвъд непрекъснатата доставка: всяка промяна, която мине проверките, излиза сама, без бутон за натискане.","also":["continuous deployment","continuous deployments","автоматично внедряване"]},{"id":"pipeline","g":"change","word":"Конвейер (Pipeline)","text":"Автоматичната поредица от стъпки, през които минава една промяна по пътя си към пускането, като изграждане, тест и внедряване.","also":["pipeline","pipelines","пайплайн"]},{"id":"environment","g":"change","word":"Среда (Environment)","text":"Едно отделно копие на системата за една цел, например едно за разработка, едно за тестване и живото.","also":["среди","environment","environments"],"noTip":1},{"id":"devenv","g":"change","word":"Среда за разработка","text":"Копието, в което работи разработчикът, често на собствения му компютър, където счупеното не вреди на никого.","also":["dev environment","development environment","dev среда"]},{"id":"testenv","g":"change","word":"Тестова среда","text":"Отделно копие на системата, ползвано само за тестване, за да не се пипа истинската услуга.","also":["тестови среди","test environment","test environments"]},{"id":"staging","g":"change","word":"Предпроизводствена среда (Staging)","text":"Последно копие, подредено точно като живото, за финална проверка преди промяната да излезе.","also":["staging","staging environment","стейджинг"]},{"id":"artifact","g":"change","word":"Артефакт от изграждането","text":"Файлът или пакетът, който изграждането създава, готов да бъде съхранен, проверен или пуснат.","also":["build artifact","build artifacts","артефакт","артефакти"]},{"id":"hotfix","g":"change","word":"Спешна поправка (Hotfix)","text":"Спешна поправка, пусната бързо, извън обичайния план, защото нещо важно е счупено.","also":["hotfix","hotfixes","хотфикс"]},{"id":"patch","g":"change","word":"Кръпка (Patch)","text":"Малко обновление, което поправя бъг или затваря дупка в сигурността. Важно е кръпките за сигурност да се слагат бързо.","also":["patch","patches","security patch","security patches","пач","кръпки за сигурност"]},{"id":"version","g":"change","word":"Номер на версията","text":"Етикет като 2.4.1, който казва коя версия имаш. Често първото число се сменя при големи промени, а последното при дребни поправки.","also":["номера на версиите","version number","version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Бележки към версията","text":"Кратък прост списък какво се е променило във версията, за хората, които я ползват, включително поправки и известни ограничения. Наричат го още changelog.","also":["release notes","changelog","change log","списък с промените"]},{"id":"flag","g":"change","word":"Превключвател на функция (Feature flag)","text":"Ключ за включване и изключване на една функция, така че новата работа да излезе скрита и да се включи (или пак да се изключи) без нова версия.","also":["feature flag","feature flags","feature toggle","feature toggles","флаг за функция"]},{"id":"rollfwd","g":"change","word":"Поправка напред (Roll forward)","text":"Оправяне на лоша версия чрез бързо пускане на нова, поправена версия, вместо връщане към старата.","also":["roll forward","rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Пробно пускане за малка група (Canary)","text":"Първо пускане на промяната за малка група и за всички едва когато изглежда наред. Името идва от канарчетата, които миньорите вземали под земята като ранно предупреждение.","also":["canary release","canary releases","canary","канарче"]},{"id":"bluegreen","g":"change","word":"Синьо-зелено внедряване","text":"Пазят се две копия на живата система и хората се прехвърлят наведнъж към новото, така че да можеш да се върнеш веднага, ако нещо не е наред.","also":["blue-green","blue green deployment","blue-green deployment"]},{"id":"zerodown","g":"change","word":"Внедряване без прекъсване","text":"Пускане на нова версия, без услугата да спира нито за миг за потребителите си.","also":["zero downtime","zero-downtime","zero-downtime deployment"]},{"id":"chgenable","g":"change","word":"Управление на промените","text":"Помощ промените да успяват: преценка на риска, получаване на нужното одобрение и избор на подходящо време. Наричат го още change management.","also":["change enablement","change management","управление на промяната"]},{"id":"cab","g":"change","word":"Съвет по промените (CAB)","text":"Група, която разглежда важните промени и се съгласява дали и кога могат да минат.","also":["CAB","change advisory board"]},{"id":"stdchange","g":"change","word":"Стандартна промяна","text":"Промяна с нисък риск, правена всеки път по един и същ изпитан начин, така че е одобрена предварително.","also":["стандартни промени","standard change","standard changes"]},{"id":"normchange","g":"change","word":"Нормална промяна","text":"Промяна, която трябва да бъде проверена и одобрена, преди да мине.","also":["нормални промени","normal change","normal changes"]},{"id":"emergchange","g":"change","word":"Спешна промяна","text":"Промяна, която трябва да стане веднага, за да се оправи или предотврати сериозна беда, затова и одобрението ѝ е по-бързо.","also":["спешни промени","emergency change","emergency changes"]},{"id":"automation","g":"change","word":"Автоматизация","text":"Компютърът сам върши повтаряща се работа, така че е по-бързо и се прави по един и същ начин всеки път.","also":["automation","automated","автоматизиране"],"noTip":1},{"id":"infra","g":"change","word":"Инфраструктура","text":"Машините, мрежите и услугите, върху които работи софтуерът.","also":["infrastructure","infra"]},{"id":"iac","g":"change","word":"Инфраструктура като код (IaC)","text":"Описване на сървърите и настройките ти във файлове, пазени заедно с кода, така че да могат да се изградят наново точно по същия начин всеки път.","also":["IaC","infrastructure as code"]},{"id":"cloud","g":"change","word":"Облак (Cloud)","text":"Наемане на компютри, място за съхранение и услуги от голям доставчик през интернет, вместо да притежаваш самите машини.","also":["cloud","the cloud","cloud computing","облачни технологии"]},{"id":"provider","g":"change","word":"Облачен доставчик","text":"Фирма, която дава под наем изчислителна мощ през интернет, като Amazon Web Services (AWS), Microsoft Azure или Google Cloud.","also":["облачни доставчици","cloud provider","cloud providers"]},{"id":"hosting","g":"change","word":"Хостинг","text":"Мястото, където живее и работи приложението или сайтът ти, та хората да стигат до него, обикновено под наем от фирма.","also":["hosting","хостване"]},{"id":"domain","g":"change","word":"Име на домейн","text":"Уеб адресът, който хората въвеждат, като example.com. Наема се за година, така че трябва да се подновява.","also":["домейни","домейн","domain name","domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Съкращение от domain name system: адресната книга на интернет, която превръща име като example.com в адреса на правилния компютър.","also":["domain name system","система за имена на домейни"]},{"id":"container","g":"change","word":"Контейнер","text":"Запечатан пакет с приложение и всичко, от което се нуждае, така че да работи по един и същ начин на всеки компютър. Docker е най-известният инструмент.","also":["контейнери","container","containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Виртуална машина (VM)","text":"Имитация на компютър, която работи вътре в истински, та една голяма машина да играе ролята на много.","also":["VM","VMs","virtual machine","virtual machines","виртуални машини"]},{"id":"serverless","g":"change","word":"Без сървъри (Serverless)","text":"Изпълнение на код, без да се грижиш за никакви сървъри: доставчикът го пуска, когато трябва, а ти плащаш за това, което ползваш."},{"id":"lb","g":"change","word":"Разпределител на натоварването","text":"Нещо, което разпределя посетителите между няколко сървъра, та нито един да не се претовари.","also":["load balancer","load balancers","балансьор"]},{"id":"cache","g":"change","word":"Кеш (Cache)","text":"Удобно хранилище на последни резултати, държано наблизо, за да не се взема или изчислява отново същото. Изчистването му може да оправи страници, които изглеждат остарели.","also":["кеширане","cache","caches","caching","cached"]},{"id":"cdn","g":"change","word":"Мрежа за доставка на съдържание (CDN)","text":"Световна мрежа от сървъри, които държат копия на страниците и снимките ти близо до посетителите, за да се зареждат бързо.","also":["CDN","content delivery network"]},{"id":"migration","g":"change","word":"Миграция","text":"Преместване на данни или системи от стара подредба към нова или внимателна промяна на устройството на база данни.","also":["миграции","migration","migrations","database migration"]},{"id":"service","g":"run","word":"Услуга","text":"Нещо, което си създал и на което хората разчитат, като уебсайт или приложение, за което се грижат, за да продължи да работи. Отметни „Този проект е услуга“ и кажи какво предлага, кой го ползва и кой е дежурен.","also":["услуги","service"]},{"id":"uptimepct","g":"run","word":"Време на работа (Uptime)","text":"Каква част от времето една услуга работи, обикновено в проценти. 99,9% още допуска около 43 минути прекъсване на месец.","also":["uptime","uptime percentage","процент време на работа"]},{"id":"uptime","g":"run","word":"Проверка на работоспособността","text":"Автоматична проверка на всеки няколко минути дали услугата ти още отговаря. Ако се провали няколко пъти поред, AI-gile сам отваря карта за инцидент.","also":["uptime checks","проверки на времето на работа"]},{"id":"statuspage","g":"run","word":"Страница за състоянието","text":"Публична страница, която показва дали услугата работи (зелено, оранжево или червено) с последната новина, за да могат ползващите я да проверят, вместо да питат.","also":["статус страница","status page"]},{"id":"desk","g":"run","word":"Бюро за обслужване","text":"Мястото, където пристигат въпроси и сигнали от хората, които ползват услугата ти. AI-gile разпределя всеки като заявка, инцидент или идея и казва, ако прилича на нещо, което вече е съобщено.","also":["бюра за обслужване","бюро за помощ","поддръжка"]},{"id":"svcrequest","g":"run","word":"Заявка за услуга","text":"Някой иска нещо обичайно, например нов акаунт или малко помощ, вместо да съобщава, че нещо е развалено. Чака реда си; инцидентът е с предимство.","also":["заявки за услуга"]},{"id":"incident","g":"run","word":"Инцидент","text":"Нещо, което е счупено или не работи както трябва за хората, които го ползват в момента, като сайт, който не работи или е много бавен. Карта с 🔥 за инцидент минава пред опашката: първо се оправя да заработи.","also":["инциденти","incident"]},{"id":"major","g":"run","word":"Голям инцидент","text":"Голям инцидент: засегнати са много хора или пари или данни са в риск. Един бутон слага всички екипи върху него (рояк), събужда дежурния и иска обновяване на състоянието на всеки 30 минути.","also":["големи инциденти","major incident"]},{"id":"oncall","g":"run","word":"Дежурство","text":"Да си този, който отговаря, когато нещо се счупи, дори през нощта. Всяка услуга има дежурен член на екипа, когото събуждат първи за нейните инциденти.","also":["дежурен","on call","on-call"]},{"id":"replyby","g":"run","word":"Срок за отговор","text":"Колко дълго една карта може да чака първи отговор, например час за инцидент. След това получава червен часовник, така че нищо да не бъде тихо забравено. Нарича се и цел за отговор.","also":["срокове за отговор","цел за отговор","response target"]},{"id":"postmortem","g":"run","word":"Анализ след инцидента","text":"Кратък поглед назад след инцидент: какво стана, какво помогна и какво да се промени, без да се обвинява никой. Инцидент не може да се затвори без такъв.","also":["post-mortem","postmortem","преглед след инцидент"]},{"id":"problem","g":"run","word":"Проблем","text":"Скритата причина зад един или повече инциденти. Карта 🧩 проблем групира инцидентите, които все се връщат, за да се намери причината и да се поправи завинаги.","also":["проблеми","problem"],"noTip":1},{"id":"rootcause","g":"run","word":"Първопричина","text":"Истинската причина нещо да се счупи, а не само това, което си видял да се обърка. Поправи първопричината и инцидентът спира да се връща.","also":["първопричини","основна причина","root cause"]},{"id":"workaround","g":"run","word":"Заобиколно решение","text":"Начин нещата да продължат да работят, докато истинската поправка е готова, например рестартиране на нещо, когато забие. Записва се на картата на проблема, за да не трябва никой да го измисля отново.","also":["заобиколни решения","workaround"]},{"id":"knownerror","g":"run","word":"Известна грешка","text":"Проблем, чиято причина е позната, но още не е поправен, обикновено със записано временно решение. „🧩 Известни грешки“ ги изброява, за да ползват всички временното решение, вместо пак да ровят.","also":["известни грешки","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Инструкции стъпка по стъпка за поправяне на познат вид проблем, за да се прави всеки път по един и същ начин и бързо. След голям инцидент екипът може да предложи такъв, за да го одобриш.","also":["runbooks","наръчник","наръчник за действие"]},{"id":"ci","g":"run","word":"Конфигурационен елемент","text":"Едно нещо, от което зависи услугата ти, например сървър, домейн, сертификат, ключ или доставчик. 🗂️ Конфигурационни елементи ги изброява за всяка услуга, за да виждаш какво засяга даден инцидент и какво трябва да се поднови или архивира.","also":["конфигурационни елементи"]},{"id":"expiry","g":"run","word":"Срок на валидност","text":"Датата, след която нещо спира да работи, освен ако не се поднови, като сертификатът за сигурност на сайт или уеб адресът му. AI-gile следи тези дати и прави по една карта за подновяване 30 дни по-рано, та нищо да не спре внезапно.","also":["срокове на валидност","изтичане","следене на изтичането"]},{"id":"backup","g":"run","word":"Резервно копие","text":"Запазено копие на данните ти от по-рано, на което да се опреш, ако нещо се изгуби или повреди. AI-gile прави резервно копие на дъските ти всеки ден.","also":["резервни копия","бекъп","backup"]},{"id":"restore","g":"run","word":"Възстановяване","text":"Връщане на данни от резервно копие. Резервното копие наистина важи чак когато знаеш, че може да се възстанови, затова си струва да го пробваш от време на време.","also":["възстанови","възстановено","restore"]},{"id":"svcreview","g":"run","word":"Преглед на услугата","text":"Поглед назад към един месец от услугата: отворени и оправени инциденти, колко бързо хората са получили отговор, време на работа и изразходвани токени. Месечният преглед показва това за всяка услуга.","also":["прегледи на услугата","месечен преглед","месечни прегледи"]},{"id":"accessreview","g":"run","word":"Преглед на достъпа","text":"Проверка на всеки 90 дни кой още може да влиза: връзки за споделяне, роли на приятели и запазени пароли и ключове. Ти запазваш или махаш всеки, та старият достъп да не остава.","also":["прегледи на достъпа"]},{"id":"improvements","g":"run","word":"Списък с подобрения","text":"Всичко, в което екипът реши да стане по-добър, на едно място: предложения от ретро, действия от прегледи и поправки на проблеми, всяко със състоянието си. Намираш го в 📈 Подобрения.","also":["списъци с подобрения","подобрения"]},{"id":"tokencap","g":"run","word":"Лимит на токените","text":"Месечен лимит на токените, които агентите на една услуга могат да използват. При 80% получаваш предупреждение; при 100% фоновата им работа чака до следващия месец или докато не вдигнеш лимита.","also":["лимити на токените"]},{"id":"svcmgmt","g":"run","word":"Управление на услуги","text":"Всичко, свързано с това една услуга да остава полезна и да работи за хората, които разчитат на нея, ден след ден.","also":["service management"]},{"id":"itil","g":"run","word":"ITIL","text":"Широко ползвано ръководство за добро управление на услуги, което обхваща неща като инциденти, проблеми и промени. Името някога означавало IT Infrastructure Library."},{"id":"itsm","g":"run","word":"Управление на ИТ услуги (ITSM)","text":"Управление на технологиите като услуга за хората, с ясни начини за справяне със заявки, инциденти, промени и подобрения.","also":["ITSM","IT service management"]},{"id":"managed","g":"run","word":"Управлявана услуга","text":"Услуга, която някой друг изпълнява и поддържа вместо теб, по споразумение колко добре трябва да работи.","also":["управлявани услуги","managed service","managed services"]},{"id":"svcowner","g":"run","word":"Собственик на услуга","text":"Човекът, който отговаря за една услуга като цяло: колко добре работи, колко струва и как се подобрява.","also":["собственици на услуги","service owner","service owners"]},{"id":"sla","g":"run","word":"Споразумение за ниво на услугата (SLA)","text":"Писмено обещание към клиентите колко добре ще работи една услуга, например „работи 99,9% от времето“ или „отговор до един час“, често с връщане на пари, ако е нарушено.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Цел за ниво на услугата (SLO)","text":"Собствената цел на екипа колко добре трябва да работи една услуга за даден период, обикновено малко по-строга от SLA за всеки случай.","also":["SLO","SLOs","service level objective"]},{"id":"sli","g":"run","word":"Показател за ниво на услугата (SLI)","text":"Действителното измерване, което сверяваш с целта, например дела на посещенията, които са се заредили добре.","also":["SLI","SLIs","service level indicator"]},{"id":"availability","g":"run","word":"Наличност (Availability)","text":"Дали хората могат да ползват услугата, когато им трябва, често измервана като време на работа.","also":["availability","high availability","висока наличност"]},{"id":"downtime","g":"run","word":"Престой (Downtime)","text":"Време, в което услугата не работи или е изключена, планирано или не.","also":["downtime","down time","прекъсване"]},{"id":"errorbudget","g":"run","word":"Бюджет за грешки","text":"Малкото количество провал, което целта ти за надеждност допуска. Докато има остатък, можеш да рискуваш с промени; щом се изчерпа, караш по-бавно.","also":["error budget","error budgets","бюджет на грешките"]},{"id":"outage","g":"run","word":"Срив (Outage)","text":"Време, в което услугата не работи или е сериозно счупена за потребителите си.","also":["сривове","outage","outages","авария"]},{"id":"degraded","g":"run","word":"Влошена работа (Degraded)","text":"Работи, но зле: бавно или с някои части, които не действат.","also":["degraded","degraded service","влошена услуга"]},{"id":"monitoring","g":"run","word":"Мониторинг","text":"Автоматично следене на услугата през цялото време, за да се забелязват проблемите, по възможност преди потребителите.","also":["наблюдение","monitoring"]},{"id":"observability","g":"run","word":"Наблюдаемост (Observability)","text":"Колко добре можеш отвън да разбереш какво става вътре в една система, чрез нейните дневници, числа и проследявания.","also":["observability","o11y"]},{"id":"log","g":"run","word":"Дневник (Log)","text":"Дневник, който една програма води постоянно за това, което прави, за да се разбере какво се е объркало.","also":["дневници","лог","логове","log","logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Проследяване (Trace)","text":"Запис как една заявка минава през различните части на системата, стъпка по стъпка, и показва къде се е забавила.","also":["trace","traces","tracing","трейс"]},{"id":"latency","g":"run","word":"Забавяне (Latency)","text":"Колко време отнема да се отговори на нещо, като чакането между кликването и появата на страницата.","also":["latency","латентност"]},{"id":"alert","g":"run","word":"Сигнал (Alert)","text":"Автоматично съобщение, че нещо иска внимание, например сайтът не отговаря.","also":["сигнали","аларма","alert","alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Умора от сигнали","text":"Когато сигналите са толкова много, че хората започват да ги пренебрегват, включително важните.","also":["alert fatigue","alarm fatigue","умора от аларми"]},{"id":"dashboard","g":"run","word":"Табло с показатели (Dashboard)","text":"Екран, който показва най-важните числа и състояния с един поглед.","also":["dashboard","dashboards","дашборд"],"noTip":1},{"id":"paging","g":"run","word":"Повикване (Paging)","text":"Спешно повикване или събуждане на дежурния заради проблем.","also":["paging","paged","пейджване"]},{"id":"escalation","g":"run","word":"Ескалация","text":"Привличане на човек с повече умения или власт, когато проблемът не може да се реши на текущото ниво или не достатъчно бързо.","also":["ескалиране","escalation","escalate","escalated"]},{"id":"triage","g":"run","word":"Сортиране по спешност (Triage)","text":"Бързо подреждане на постъпилите проблеми по спешност и важност, така че най-лошото да се поеме първо.","also":["triage","triaged","триаж"]},{"id":"impact","g":"run","word":"Въздействие (Impact)","text":"Колко нещо засяга хората: колко на брой и колко силно.","noTip":1},{"id":"urgency","g":"run","word":"Спешност (Urgency)","text":"Колко бързо трябва да се занимаеш с нещо. Въздействието и спешността заедно определят приоритета.","noTip":1},{"id":"plevels","g":"run","word":"Нива на приоритет (P1, P2…)","text":"Етикети за това колко е спешен един проблем. P1 е най-сериозният и иска действие веднага.","also":["P1","P2","P3","P4","нива на приоритет"]},{"id":"queue","g":"run","word":"Опашка от тикети","text":"Списъкът със заявки и инциденти, които чакат да бъдат поети.","also":["опашки от тикети","ticket queue","ticket queues","опашка със заявки"]},{"id":"tiers","g":"run","word":"Първа линия и втора линия","text":"Нива на поддръжка: първата линия вдига телефона и оправя простите неща; втората има по-задълбочени умения за по-трудните. Наричат се още tier 1 и tier 2.","also":["първа линия","втора линия","first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Ръководител на инцидента","text":"Единственият човек, който води реакцията на един инцидент, та всички да знаят кой решава и кой какво прави.","also":["ръководители на инцидент","incident commander","incident commanders"]},{"id":"responsetime","g":"run","word":"Време за реакция","text":"Колко време минава, преди някой за първи път да поеме заявка или инцидент.","also":["времена за реакция","response time","response times"]},{"id":"resolution","g":"run","word":"Време за решаване","text":"Колко време отнема напълно да се уреди заявка или инцидент, от съобщението до поправката.","also":["времена за решаване","resolution time","resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Средно време за възстановяване (MTTR)","text":"Средно колко време е нужно, за да заработи услугата отново, след като се счупи. MTTR може да значи малко различни неща, затова кажи какво точно измерваш.","also":["MTTR","mean time to restore","mean time to recover"]},{"id":"mtbf","g":"run","word":"Средно време между откази (MTBF)","text":"Средно колко време една услуга работи, преди нещо да се счупи.","also":["MTBF","mean time between failures"]},{"id":"cmdb","g":"run","word":"База данни за управление на конфигурациите (CMDB)","text":"Списъкът на всички твои конфигурационни елементи и как са свързани, за да виждаш какво от какво зависи.","also":["CMDB","configuration management database"]},{"id":"asset","g":"run","word":"Актив","text":"Всичко ценно, което притежаваш или плащаш, за да върви услугата, като лаптоп, софтуерен лиценз или домейн.","also":["активи","asset","assets"],"noTip":1},{"id":"capplan","g":"run","word":"Планиране на капацитета","text":"Грижа да има достатъчно изчислителна мощ, място за съхранение и хора за предстоящото.","also":["capacity planning","capacity plan","план за капацитет"]},{"id":"scaling","g":"run","word":"Мащабиране","text":"Справяне с повече потребители чрез по-мощна машина (вертикално мащабиране, scaling up) или повече машини (хоризонтално мащабиране, scaling out).","also":["scaling","scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Непрекъснатост на дейността","text":"Планове как да вървят важните неща, когато нещо голямо се обърка, като загуба на офис, ключов доставчик или компютрите.","also":["business continuity","business continuity plan","план за непрекъсваемост"]},{"id":"dr","g":"run","word":"Възстановяване след бедствие (DR)","text":"Планът и средствата за връщане на услугата след нещо сериозно, като загуба на цял център за данни.","also":["disaster recovery","DR"]},{"id":"rto","g":"run","word":"Целево време за възстановяване (RTO)","text":"Най-дългото време, в което една услуга може да е спряла след бедствие, преди да трябва да работи отново.","also":["RTO","recovery time objective"]},{"id":"rpo","g":"run","word":"Целева точка за възстановяване (RPO)","text":"Колко скорошни данни можеш да си позволиш да загубиш, измерено във време. RPO от един час значи резервни копия поне на всеки час.","also":["RPO","recovery point objective"]},{"id":"redundancy","g":"run","word":"Резервираност","text":"Наличие на готови резерви, като втори сървър, така че един отказ да не спира услугата.","also":["резервиране","redundancy"]},{"id":"failover","g":"run","word":"Автоматично превключване (Failover)","text":"Автоматично преминаване към резервна система, когато обичайната откаже.","also":["failover","fail over","превключване при отказ"]},{"id":"spof","g":"run","word":"Единична точка на отказ","text":"Една част, която повлича всичко със себе си, когато се счупи, защото няма резерва.","also":["единични точки на отказ","single point of failure","single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Прозорец за поддръжка","text":"Планирано време, когато услугата може да е спряна или бавна заради поддръжка, обявено на потребителите предварително.","also":["прозорци за поддръжка","maintenance window","maintenance windows","planned maintenance","планирана поддръжка"]},{"id":"handover","g":"run","word":"Предаване на работата (Handover)","text":"Предаване на работа, знания и отговорност на друг човек или екип, та нищо да не се изпусне.","also":["handover","handovers","предаване"]},{"id":"kb","g":"run","word":"База знания","text":"Колекция от помощни статии и отговори, за потребителите и за екипа.","also":["бази знания","knowledge base","knowledge bases"]},{"id":"csat","g":"run","word":"Удовлетвореност на клиентите (CSAT)","text":"Оценка от потребителите колко доволни са били, често искана след приключване на заявка.","also":["CSAT","customer satisfaction"]},{"id":"supplier","g":"run","word":"Доставчик","text":"Външна фирма, на която разчиташ, като хостинг доставчика ти. Наричат я още vendor или трета страна.","also":["доставчици","supplier","suppliers","vendor","vendors","third party","трета страна"],"noTip":1},{"id":"retire","g":"run","word":"Спиране на услуга","text":"Изключване на услуга завинаги по безопасен начин: предупреждаване на потребителите, справяне с данните и достъпа ѝ и спиране на разходите.","also":["изваждане от употреба","service retirement","retiring a service"]},{"id":"eol","g":"run","word":"Край на живота (EOL)","text":"Когато производителят спре да дава обновления или поддръжка за един продукт и той трябва да се замени.","also":["EOL","end-of-life","end of life"]},{"id":"cybersec","g":"sec","word":"Киберсигурност","text":"Защита на системите и данните от проникване, кражба или повреда.","also":["cybersecurity","cyber security","кибер сигурност"]},{"id":"authn","g":"sec","word":"Удостоверяване (Authentication)","text":"Проверка кой е някой, обикновено с парола или код. Често се съкращава authn.","also":["authentication","authn","автентикация"]},{"id":"authz","g":"sec","word":"Упълномощаване (Authorisation)","text":"Проверка какво е позволено на някого, след като вече знаеш кой е. Често се съкращава authz.","also":["authz","authorization","авторизация"]},{"id":"mfa","g":"sec","word":"Многофакторно удостоверяване (MFA)","text":"Влизане с две или повече доказателства, като парола плюс код на телефона ти. Наричат го още двуфакторно (2FA).","also":["MFA","2FA","two-factor","two-factor authentication","двуфакторно удостоверяване"]},{"id":"sso","g":"sec","word":"Единен вход (SSO)","text":"Влизаш веднъж и получаваш достъп до много системи, като ползваш служебния си акаунт навсякъде.","also":["SSO","single sign-on","единен вход","еднократно влизане"]},{"id":"pwmgr","g":"sec","word":"Мениджър на пароли","text":"Приложение, което създава силни пароли и ги помни вместо теб.","also":["мениджъри на пароли","password manager","password managers"]},{"id":"secret","g":"sec","word":"Тайна (Secret)","text":"Парола, ключ или друг таен код, с който една програма влиза в нещо. Никога не бива да се споделя или да се записва в кода.","also":["тайни","secret","secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"API ключ","text":"Таен код, който позволява на програма да ползва API на друга услуга и показва кой я ползва (и плаща за нея).","also":["API ключове","API key","API keys"]},{"id":"accesstoken","g":"sec","word":"Токен за достъп","text":"Временен пропуск, който доказва, че на програмата е позволено да влезе, така че да не ѝ трябва паролата ти всеки път. Не е същото като AI токен.","also":["токени за достъп","access token","access tokens"]},{"id":"encryption","g":"sec","word":"Криптиране","text":"Разбъркване на информацията, така че само който има правилния ключ, да може да я прочете.","also":["шифроване","криптирани","encryption","encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"Сигурният начин, по който уеб страниците пътуват, показан с катинарчето в браузъра ти, та никой по пътя да не може да ги чете или променя."},{"id":"cert","g":"sec","word":"SSL/TLS сертификат","text":"Дигитална лична карта, с която един сайт доказва кой е и може да ползва HTTPS. Изтича, така че трябва да се подновява.","also":["TLS сертификат","SSL сертификат","сертификат","сертификати","TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Права","text":"Правилата кой какво може да вижда или променя.","also":["разрешения","права за достъп","permissions","permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Най-малки права (Least privilege)","text":"Всеки човек или програма получава само достъпа, от който наистина се нуждае, и само докато му е нужен.","also":["принцип на най-малките права","least privilege","principle of least privilege"]},{"id":"rbac","g":"sec","word":"Контрол на достъпа по роли (RBAC)","text":"Даване на достъп по роля, като зрител или редактор, вместо човек по човек.","also":["RBAC","role-based access","role-based access control"]},{"id":"vuln","g":"sec","word":"Уязвимост","text":"Слабост, която някой би могъл да използва, за да проникне или да навреди.","also":["уязвимости","vulnerability","vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day (нулев ден)","text":"Слабост, за която нападателите знаят, преди създателите да са имали време да я поправят.","also":["zero-day","zero-days","zero day","нулев ден"]},{"id":"malware","g":"sec","word":"Зловреден софтуер (Malware)","text":"Вреден софтуер, като вируси, направен да поврежда, шпионира или краде.","also":["malware"]},{"id":"ransomware","g":"sec","word":"Рансъмуер (Ransomware)","text":"Зловреден софтуер, който заключва файловете ти и иска пари да ги отключи. Добрите резервни копия са най-добрата защита.","also":["ransomware","ransomware attack","вирус за откуп","рансъмуер"]},{"id":"phishing","g":"sec","word":"Фишинг (Phishing)","text":"Фалшиви съобщения, които се опитват да те подмамят да издадеш пароли или пари или да отвориш нещо вредно.","also":["phishing","phishing email","phishing emails","фишинг имейл","фишинг имейли"]},{"id":"socialeng","g":"sec","word":"Социално инженерство","text":"Мамене на хора, а не на компютри, за да дадат достъп, като фалшиво обаждане от „ИТ поддръжка“."},{"id":"firewall","g":"sec","word":"Защитна стена (Firewall)","text":"Пазач, който решава какъв мрежов трафик може да влиза или да излиза.","also":["firewall","firewalls","файървол","защитни стени"]},{"id":"vpn","g":"sec","word":"VPN","text":"Съкращение от virtual private network (виртуална частна мрежа): частна, шифрована връзка през интернет, често ползвана за безопасен достъп до служебни системи.","also":["virtual private network","виртуална частна мрежа"]},{"id":"ddos","g":"sec","word":"Отказ на услуга (DoS, DDoS)","text":"Заливане на услуга с толкова много фалшив трафик, че истинските хора не могат да я ползват. DDoS значи, че идва от много компютри едновременно.","also":["DoS","DDoS","denial of service","DDoS attack","DDoS атака"]},{"id":"pentest","g":"sec","word":"Тест за проникване (pen test)","text":"Наемане на приятелски настроени експерти, които се опитват да проникнат, та слабостите да се намерят, преди да ги намерят истинските нападатели.","also":["pen test","pen testing","penetration test","penetration testing","pentest","пентест"]},{"id":"audit","g":"sec","word":"Одит на сигурността","text":"Внимателна проверка колко добре е защитено нещо, спрямо списък с добри практики.","also":["одити на сигурността","security audit","security audits"]},{"id":"threatmodel","g":"sec","word":"Моделиране на заплахите","text":"Обмисляне кой би могъл да нападне нещо, как и какво ще направиш, за да го спреш.","also":["threat model","threat modelling","threat modeling","модел на заплахите"]},{"id":"breach","g":"sec","word":"Изтичане на данни","text":"Когато лична информация стигне до хора, които не бива да я имат, или се изгуби или промени без разрешение.","also":["пробив в данните","data breach","data breaches"]},{"id":"pii","g":"sec","word":"Лични данни","text":"Всяка информация за човек, който може да бъде разпознат, като име, имейл адрес или местоположение. Наричат се още PII.","also":["PII","personally identifiable information","лична информация"]},{"id":"gdpr","g":"sec","word":"GDPR (ОРЗД)","text":"Европейският закон за личните данни (Великобритания има своя версия): събирай само нужното, пази го сигурно и дай възможност на хората да виждат или трият своите.","also":["GDPR","ОРЗД","General Data Protection Regulation","Общ регламент относно защитата на данните"]},{"id":"dataprot","g":"sec","word":"Защита на данните","text":"Грижа за личните данни както трябва и в рамките на закона.","also":["data protection","data protection law","закон за защита на данните"]},{"id":"privacypolicy","g":"sec","word":"Политика за поверителност","text":"Публична страница, която казва какви лични данни събираш, защо и какво правиш с тях.","also":["privacy policy","privacy statement","privacy notice","декларация за поверителност"]},{"id":"consent","g":"sec","word":"Съгласие","text":"Ясно и свободно „да“ на човек данните му да се ползват по определен начин. Може да го оттегли по всяко време.","also":["consent","opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Бисквитка (Cookie)","text":"Малък файл, който един сайт записва в браузъра ти, за да помни неща, например влизането ти в профила. За някои първо е нужно съгласието ти.","also":["бисквитки","cookie","cookies","кукита"],"noTip":1},{"id":"minimisation","g":"sec","word":"Свеждане на данните до минимум","text":"Събиране и пазене само на личните данни, които наистина са нужни за работата.","also":["минимизиране на данните","data minimisation","data minimization"]},{"id":"retention","g":"sec","word":"Срок на съхранение на данни","text":"Колко дълго се пазят данните, преди да бъдат изтрити. Да не се пазят по-дълго от нужното е по-безопасно и често е изискване на закона.","also":["съхранение на данни","data retention","retention period"]},{"id":"anon","g":"sec","word":"Анонимизиране","text":"Промяна на данните така, че вече никой да не може основателно да бъде разпознат по тях.","also":["анонимизирани данни","anonymisation","anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"Псевдонимизиране","text":"Замяна на имена и други подробности с кодове, с ключ, пазен отделно, за да се свържат обратно. Това все още са лични данни.","also":["pseudonymisation","pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Споразумение за обработка на данни (DPA)","text":"Договор, който определя как един доставчик може да борави с лични данни от твое име.","also":["DPA","data processing agreement"]},{"id":"dpia","g":"sec","word":"Оценка на въздействието върху защитата на данните (DPIA)","text":"Внимателен поглед, преди да започнеш, как планът за ползване на лични данни може да засегне хората и как да се намалят рисковете.","also":["DPIA","data protection impact assessment"]},{"id":"auditlog","g":"sec","word":"Одитен дневник","text":"Запис кой какво е направил и кога, за да могат действията да се проверят по-късно.","also":["одитни дневници","audit log","audit logs","audit trail","одитна следа"]},{"id":"compliance","g":"sec","word":"Съответствие (Compliance)","text":"Спазване на законите, правилата и стандартите, които важат за теб, и възможност да докажеш, че го правиш.","also":["спазване на изискванията","compliance","compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"Добре познат международен стандарт за управление на информационната сигурност. Фирмите могат да бъдат сертифицирани по него.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"Американски доклад, проверен от външни одитори, който показва, че една фирма се грижи правилно за данните на клиентите.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Агент","text":"AI, който сам работи по задача: чете кода, прави промени, пуска проверки и докладва. Работата му все пак се проверява.","also":["агент","агента","агенти","агентите","agent","agents"]},{"id":"token","g":"ai","word":"Токен","text":"Малките късчета текст, които AI чете и пише, около три четвърти от дума всяко. Ползването на AI се брои в токени, така че по-малко токени оставят повече от плана ти.","also":["токен","токена","токени","токените","token","tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"Малка команда, която се пуска сама в определен момент, например когато започне AI сесия, за да чува екипът коментарите ти.","also":["hook","hook-ове","hook-а","hooks"]},{"id":"ai","g":"ai","word":"Изкуствен интелект (AI)","text":"Компютърни системи, които правят неща, за които обикновено мислим, че трябва човек, като писане, отговаряне на въпроси или разпознаване на снимки.","also":["AI","artificial intelligence","ИИ"],"noTip":1},{"id":"ml","g":"ai","word":"Машинно обучение (ML)","text":"Начин компютрите да научават закономерности от много примери, вместо да им се дават точни правила.","also":["machine learning","ML"]},{"id":"model","g":"ai","word":"Модел","text":"Обученият „мозък“ на една AI система, създаден чрез учене от огромен брой примери. Моделите се различават по умения, скорост и цена.","also":["модели","AI модел","model","models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"Голям езиков модел (LLM)","text":"AI модел, обучен върху огромни количества текст, така че да може да чете и пише на човешки език.","also":["LLM","LLMs","large language model"]},{"id":"genai","g":"ai","word":"Генеративен AI","text":"AI, който създава нови неща, като текст, картини или код, а не само сортира или разпознава.","also":["GenAI","generative AI","генеративен изкуствен интелект"]},{"id":"chatbot","g":"ai","word":"Чатбот","text":"Програма, с която разговаряш на обикновен език, писмено или на глас.","also":["чатботове","chatbot","chatbots"]},{"id":"prompt","g":"ai","word":"Промпт (Prompt)","text":"Това, което даваш на AI: въпроса или указанията ти, плюс всичко, което му подаваш. По-ясните промптове обикновено дават по-добри отговори.","also":["промптове","prompt","prompts","запитване"]},{"id":"prompteng","g":"ai","word":"Писане на промптове (Prompt engineering)","text":"Умението да пишеш промптове, които дават надеждни, полезни резултати.","also":["prompt engineering","промпт инженерство"]},{"id":"sysprompt","g":"ai","word":"Системен промпт","text":"Фонови указания, които AI получава, преди разговорът да започне, и определят ролята и правилата му. Тежат повече от това, което пишеш ти.","also":["системни промптове","system prompt","system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Контекст","text":"Всичко, което AI вижда, докато работи: указанията, твоите съобщения, прочетените файлове и по-ранните отговори.","noTip":1},{"id":"ctxwin","g":"ai","word":"Контекстен прозорец","text":"Колко може AI да държи в ума си наведнъж, измерено в токени. Отвъд това по-старите части се изпускат или резюмират.","also":["контекстни прозорци","context window","context windows"]},{"id":"session","g":"ai","word":"Сесия","text":"Един работен разговор с AI, от началото до края. Новата сесия започва със свежа памет.","also":["сесии","session","sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Памет","text":"Бележки, които AI пази между сесиите, за да помни предпочитанията ти и предишните решения.","noTip":1},{"id":"hallucination","g":"ai","word":"Халюцинация","text":"Когато AI казва нещо, което звучи уверено, но е измислено или грешно. Проверявай важните факти.","also":["халюцинации","hallucination","hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Обучение","text":"Обучаване на модел, като му се показват огромен брой примери, преди някой да го използва.","also":["обучаване","training","trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Данни за обучение","text":"Примерите, от които е учил един модел. Знанията му стигат до датата, до която са събирани тези данни.","also":["training data","training set"]},{"id":"cutoff","g":"ai","word":"Граница на знанията","text":"Датата, до която стигат вградените знания на AI. Той няма да знае за по-късни неща, освен ако не ги потърси.","also":["knowledge cutoff","training cutoff","дата на отсичане"]},{"id":"finetune","g":"ai","word":"Дообучаване (Fine-tuning)","text":"Допълнително обучение на готов модел върху твои собствени примери, за да стане по-добър в една определена работа.","also":["fine-tuning","fine-tune","fine-tuned","fine tuning","фина настройка"]},{"id":"inference","g":"ai","word":"Извод (Inference)","text":"AI моделът да се ползва наистина, за да отговори на нещо, за разлика от обучението му.","also":["inference","model inference","инференс"]},{"id":"tooluse","g":"ai","word":"Работа с инструменти","text":"AI да може да върши неща, а не само да говори: да пуска команди, да чете файлове или да търси в мрежата чрез инструменти, които приложението му дава.","also":["tool use","tool calling","tool call","tool calls","използване на инструменти"]},{"id":"subagent","g":"ai","word":"Подагент (Subagent)","text":"Помощен AI, на когото главният AI възлага по-малка задача и от когото получава резултата.","also":["подагенти","subagent","subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Много агенти (Multi-agent)","text":"Няколко AI работят заедно върху една работа, всеки със своя дял, като малък екип.","also":["multi-agent","multi-agent system","мултиагентна система"]},{"id":"autonomy","g":"ai","word":"Самостоятелност (Autonomy)","text":"Колко може AI да прави сам, преди да трябва да пита човек.","also":["autonomy","autonomous","автономност"]},{"id":"hitl","g":"ai","word":"Човек в цикъла","text":"Човек остава включен, за да проверява или одобрява какво прави AI в ключови моменти. В AI-gile това си ти.","also":["human in the loop","human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Ограничители (Guardrails)","text":"Граници и проверки, които държат действията на AI безопасни, като необходимост от одобрение, преди нещо да излезе. Намаляват риска от грешки, но не го изключват.","also":["guardrails","guardrail","предпазни парапети"]},{"id":"rag","g":"ai","word":"Генериране, допълнено с търсене (RAG)","text":"AI да търси в собствените ти документи, преди да отговори, така че отговорите му да почиват на твоите факти.","also":["RAG","retrieval-augmented generation","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Вграждане (Embedding)","text":"Превръщане на текст в списък от числа, който улавя смисъла му, така че компютърът да намира неща със сходно значение.","also":["embedding","embeddings","ембединг"]},{"id":"vectordb","g":"ai","word":"Векторна база данни","text":"База данни, направена да търси в тези списъци от числа (вграждания), за да намира материали със сходен смисъл.","also":["векторни бази данни","vector database","vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"Общ начин да се включват инструменти и източници на данни в AI приложения, за да може AI да ги ползва.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Температура","text":"Настройка колко дръзки са отговорите на AI. Ниската дава по-устойчиви и предвидими отговори, високата по-разнообразни. Нито една от двете не гарантира, че отговорът е верен.","also":["temperature","model temperature","температура на модела"],"noTip":1},{"id":"multimodal","g":"ai","word":"Мултимодален","text":"Може да работи с повече от един вид информация, като текст, картини и звук.","also":["multimodal","multi-modal"]},{"id":"evals","g":"ai","word":"Оценяване (eval)","text":"Планиран тест колко добре се справя AI с избрани примери, за да можеш да сравняваш модели или промптове.","also":["eval","evals","evaluation","оценки на модели"]},{"id":"bias","g":"ai","word":"Предубеденост (Bias)","text":"Когато AI (или човек) несправедливо клони на една страна, често заради онова, от което е учил.","also":["пристрастност","bias","biased"],"noTip":1},{"id":"responsible","g":"ai","word":"Отговорен AI","text":"Ползване на AI справедливо, безопасно и честно, като хората продължават да отговарят за резултатите.","also":["responsible AI","ethical AI","етичен AI"]},{"id":"injection","g":"ai","word":"Инжектиране на промпт","text":"Трик, при който скрити указания в уеб страница или файл се опитват да накарат AI да направи нещо, което потребителят му не е поискал.","also":["prompt injection","prompt injections","промпт инжекция"]},{"id":"ratelimit","g":"ai","word":"Ограничение на заявките","text":"Таван на броя заявки, които можеш да пратиш на една услуга за зададено време. Надвишиш ли го, трябва да почакаш.","also":["rate limit","rate limits","rate limited","лимит на заявките"]},{"id":"usagelimit","g":"ai","word":"Лимит на ползване","text":"Колко AI работа позволява планът ти за даден период, след което спира или струва повече.","also":["usage limit","usage limits","лимити на ползване"]},{"id":"vibe","g":"ai","word":"Vibe coding (кодене по усещане)","text":"Създаване на софтуер най-вече като описваш на AI какво искаш и го оставяш да напише кода.","also":["vibe-coding","вайб кодинг"]},{"id":"budget","g":"money","word":"Бюджет","text":"Сумата пари, заделена за нещо.","also":["бюджети","budget","budgets"],"noTip":1},{"id":"costest","g":"money","word":"Оценка на разходите","text":"Най-доброто предположение колко ще струва нещо, преди да започнеш.","also":["cost estimate","cost estimates","ориентировъчна цена"]},{"id":"roi","g":"money","word":"Възвръщаемост на инвестицията (ROI)","text":"Какво получаваш обратно в сравнение с вложеното. Ако е положително, си е струвало.","also":["ROI","return on investment"]},{"id":"tco","g":"money","word":"Обща цена на притежание (TCO)","text":"Всичко, което нещо наистина струва през целия си живот, а не само цената за купуване: работа, поддръжка, надграждане и накрая спиране.","also":["TCO","total cost of ownership"]},{"id":"capex","g":"money","word":"CapEx и OpEx","text":"CapEx са пари, похарчени отведнъж за неща, които пазиш; OpEx са текущите разходи, като месечните сметки.","also":["CapEx","OpEx","capital expenditure","operating expenditure","капиталови разходи","оперативни разходи"]},{"id":"subscription","g":"money","word":"Абонамент","text":"Редовно плащане, обикновено месечно или годишно, за да продължиш да ползваш нещо.","also":["абонаменти","subscription","subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Софтуер като услуга (SaaS)","text":"Софтуер, който ползваш онлайн и плащаш с абонамент, а създателят му го поддържа вместо теб.","also":["SaaS","software as a service"]},{"id":"payg","g":"money","word":"Плащане при ползване","text":"Плащаш само за това, което ползваш, като при облачните изчисления или AI токените.","also":["pay as you go","pay-as-you-go","usage-based pricing","плащане според ползването"]},{"id":"overage","g":"money","word":"Надвишаване на плана","text":"Ползване над включеното в плана ти, което може да струва допълнително.","also":["overage","overages","overage charges","такси за надвишаване"]},{"id":"billingalert","g":"money","word":"Сигнал за сметка","text":"Съобщение, когато разходите или ползването стигнат избрано от теб ниво. Предупреждава те, но не винаги спира по-нататъшни такси.","also":["billing alert","billing alerts","spending alert","сигнал за разходи"]},{"id":"freetier","g":"money","word":"Безплатно ниво","text":"Безплатно ниво на платена услуга, с ограничения. Удобно за начало.","also":["безплатен план","free tier","free plan"]},{"id":"pricing","g":"money","word":"Ценови план","text":"Различните пакети, които една услуга продава, всеки със своя цена и ограничения.","also":["ценови планове","pricing plan","pricing plans","price plan"]},{"id":"licence","g":"money","word":"Лиценз","text":"Правилата как можеш да ползваш, копираш, променяш или споделяш нещо, направено от друг, като софтуер, шрифтове или картини.","also":["лицензи","licence","licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Отворен код (Open source)","text":"Софтуер, чийто код всеки може да чете, ползва и често променя безплатно, по правилата на лиценза му.","also":["open source","open-source","open source software","OSS","софтуер с отворен код"]},{"id":"osslicence","g":"money","word":"Лиценз за отворен код","text":"Правилата, които идват с отворения код. Някои позволяват почти всичко (като MIT); други искат да споделиш и твоите промени (като GPL).","also":["лицензи за отворен код","open source licence","open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Собственически (Proprietary)","text":"Притежаван от фирма и не е свободен за копиране или промяна. Обратното на отворения код.","also":["proprietary","proprietary software","собственически софтуер","затворен код"]},{"id":"copyright","g":"money","word":"Авторско право","text":"Законното право на създателя да контролира копията на творбата си, включително код и текст.","also":["copyright","copyrighted","авторски права"],"noTip":1},{"id":"ip","g":"money","word":"Интелектуална собственост (IP)","text":"Идеи и творби, които законът смята за притежавани, като код, дизайн, имена и лога.","also":["IP","intellectual property"]},{"id":"tos","g":"money","word":"Условия за ползване","text":"Правилата, с които се съгласяваш, когато ползваш една услуга.","also":["terms of service","terms and conditions","terms of use","общи условия"]},{"id":"contract","g":"money","word":"Договор","text":"Писмено споразумение между две страни, което законът ще подкрепи.","also":["договори","contract","contracts"],"noTip":1},{"id":"sow","g":"money","word":"Задание за работата (SOW)","text":"Документ, който описва точно каква работа ще се свърши, до кога и за колко.","also":["SOW","statement of work"]},{"id":"fixedprice","g":"money","word":"Фиксирана цена","text":"Договорена цена за цялата работа, колкото и време да отнеме.","also":["fixed price","fixed-price"]},{"id":"tm","g":"money","word":"Време и материали","text":"Плащане за наистина отработените часове и наистина използваните неща, а не за твърда цена.","also":["time and materials","T&M"]},{"id":"invoice","g":"money","word":"Фактура","text":"Сметка, която иска плащане за свършена работа или доставени стоки.","also":["фактури","invoice","invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Зависимост от доставчик (Vendor lock-in)","text":"Когато напускането на един доставчик е толкова трудно или скъпо, че няма как да се откъснеш от него.","also":["vendor lock-in","lock-in","заключване при доставчик"]},{"id":"procurement","g":"money","word":"Доставки и покупки (Procurement)","text":"Процесът на избиране и купуване от доставчици.","also":["procurement","обществени поръчки"]},{"id":"servicecredit","g":"money","word":"Кредит за услугата","text":"Върнати пари или отстъпка, когато доставчикът не спази SLA.","also":["service credit","service credits","кредити за услугата"]}]}};
